(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0000.js"] = [{"id":"glyph-kai-4e00","script":"kai","character":"一","reading":"yī","description":"yī：(1)数名，最小的正整数（在钞票和单据上常用大写壹”代）。\n(2)纯；专专～。～心～意。\n(3)全；满～生。～地水。\n(4)相同～样。颜色不～。\n(5)另外的蟋蟀～名促织。\n(6)表示动作短暂，或是一次，或具试探性算～算。试～试。\n(7)乃；竞～至于此。\n(8)部分联成整体统～。整齐划～。\n(9)或者～胜～负。\n(10)初次～见如故。\n(11)助词，表示程度深吏呼～何怒，妇啼～何苦！”\n(12)中国古代乐谱记音符号，相当于简谱7”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-一"},{"id":"glyph-kai-4e01","script":"kai","character":"丁","reading":"dīng；zhēng","description":"dīng：(1)天干的第四位，用于作顺序第四的代称～是～，卯是卯。\n(2)成年男子。\n(3)人口。\n(4)从事某种劳动的人园～。\nzhēng：〔～～〕象声词，形容伐木、下棋、弹琴的声音。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丁"},{"id":"glyph-kai-4e03","script":"kai","character":"七","reading":"qī","description":"qī：(1)数名，六加一（在钞票和单据上常用大写柒”代）。\n(2)文体名，或称七体”，为赋体的另一种形式。\n(3)旧时人死后每隔七天一祭，共七次，称做七”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-七"},{"id":"glyph-kai-4e07","script":"kai","character":"万","reading":"wàn","description":"虫名。蝎。\n古代的一种舞名\n古州名\n⒈数目字十千为一～。\n⒉多，一切～般。～物。千家～户。千军～马。～象更新。\n⒊极，很，绝对～端。～难。～无一失。～全之策。\n①万分之一。\n②意外，意外的～一出错。防止～一。\n③倘若，如果～一他不干，就请别人干。\n①千秋万代，永远存在。\n②〈表〉欢呼或棕人民～岁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-万"},{"id":"glyph-kai-4e08","script":"kai","character":"丈","reading":"zhàng","description":"zhàng：(1)中国市制长度单位，十尺万～高楼。\n(2)测量长度和面积～量（liáng）。\n(3)对老年男子的尊称～人（a.古代对老人的尊称；b.岳父。人”均读轻声）。老～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丈"},{"id":"glyph-kai-4e09","script":"kai","character":"三","reading":"sān","description":"sān：(1)数名，二加一（在钞票和单据上常用大写叁”代）～维空间。～部曲。～国（中国朝代名）。\n(2)表示多次或多数～思而行。～缄其口。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-三"},{"id":"glyph-kai-4e0a","script":"kai","character":"上","reading":"shàng；shǎng","description":"shàng：(1)位置在高处的，与下”相对楼～。～边。\n(2)次序或时间在前的～古。～卷。\n(3)等级和质量高的～等。～策。～乘（佛教用语，一般借指文学艺术的高妙境界或上品）。\n(4)由低处到高处～山。～车。～升。\n(5)去，到～街。\n(6)向前进冲～去。\n(7)增加～水。\n(8)安装，连缀～刺刀。～鞋（亦作绱鞋”）。\n(9)涂～药。\n(10)按规定时间进行或参加某种活动～课。～班。\n(11)拧紧发条～弦。\n(12)登载，记～账。\n(13)用在名词后边，表示时间、处所、范围晚～。桌～。组织～。\n(14)用在动词后边，表示开始、继续、趋向、完成爬～来。锁～。选～代表。\n(15)达到一定的程度或数量～年纪。\n(16)中国古代乐谱的记音符号，相当于简谱1”的高音。\n下；\nshǎng：〔～声〕汉语声调之一，普通话上声（第三声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-上"},{"id":"glyph-kai-4e0b","script":"kai","character":"下","reading":"xià","description":"xià：(1)位置在低处的，与上”相对～层。～款。\n(2)等级低的～级。～品。～乘（佛教用语，一般借指文学艺术的平庸境界或下品）。～里巴人（泛指通俗的普及的文学艺术，常与阳春白雪”对举）。\n(3)方面，方位两～都同意。\n(4)次序或时间在后的～卷。～次。～限。\n(5)由高处往低处，降落～山。～车。～马。～达。\n(6)使降落～半旗。～棋。\n(7)进入～海。\n(8)投送～书。\n(9)到规定时间结束日常工作或学习～班。～课。\n(10)谦辞在～。～官。\n(11)颁布～令。\n(12)攻克攻～。\n(13)卸掉～货。把他的枪～了。\n(14)用，投入精力～工夫。\n(15)退让争执不～。\n(16)做出判断～结论。\n(17)量词，指动作次数打三～。\n(18)用在名词后边（ａ．表示在里面，如心～”、言～”；ｂ．表示当某个时节，如节～”、年～”）。\n(19)用在动词后边（ａ．表示关系，如教导～”、培养～”；ｂ．表示完成或结果，如打～基础”；ｃ．与来”、去”连用表示趋向或继续，如走～去”、停～来”）。\n(20)少于不～二百人。\n(21)动物生产鸡～蛋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-下"},{"id":"glyph-kai-4e0d","script":"kai","character":"不","reading":"bù","description":"用在动词、形容词或个别副词前,表示否定","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-不"},{"id":"glyph-kai-4e0e","script":"kai","character":"与","reading":"yǔ","description":"则与斗卮酒。\n⒈跟，同，和～众不同。～虎谋皮。我～你们一道走。\n⒉给，授予交～。送～。赠～。\n⒋赞许，帮助朝过夕改，君子～之。君不～胜者，而～不胜者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-与"},{"id":"glyph-kai-4e10","script":"kai","character":"丐","reading":"gài","description":"gài：(1)乞求。\n(2)讨饭的人乞～。\n(3)给与、施与沾～后人多矣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丐"},{"id":"glyph-kai-4e11","script":"kai","character":"丑","reading":"chǒu","description":"可恶\n污秽\n①丑陋；难看。\n②令人厌恶或瞧不起的～态百出、丢～。\n③戏曲角色。扮演滑稽人物，鼻梁上抹白粉，有文丑、武丑的区别。又叫小花脸或三花脸。\n④地支的第二位。\n⑤姓。\n【丑剧】指丑恶的富有戏剧性的事件。\n【丑类】指恶人，坏人。\n【丑时】旧式计时法指夜里1点到3点的时间。\n⒈地支的第二位，也用作次序第二。\n⒊戏曲、杂技里的一种角色～角。\n⒋相貌难看，跟\"美\"相对～陋。〈喻〉可耻的、可厌恶的或不光荣的～事。现～。家～外扬。～态百出。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丑"},{"id":"glyph-kai-4e13","script":"kai","character":"专","reading":"zhuān","description":"纺专,收丝器\n专长\n独占;独用\n⒈独，独有，独占～断。～利。～权。～制。独断～行。\n⒉单纯，单一，集中在某一方面～注。～一。～心。～业。～选重担挑。\n①特定的门类～门学问。\n专tuán 1.聚集。参见\"尃生\"。 2.圆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-专"},{"id":"glyph-kai-4e14","script":"kai","character":"且","reading":"qiě；jū","description":"qiě：(1)尚，还，表示进一层既高～大。尚～。况～。\n(2)表示暂时苟～偷安。姑～。\n(3)表示将要、将近城～拔矣。年～九十。\n(4)一面这样，一面那样～走～说。\n(5)表示经久这双鞋～穿呢！\n(6)文言发语词，用在句首，与夫”相似～说。\n(7)姓。\njū：(1)文言助词，用在句末，与啊”相似。\n(2)多的样子。\n(3)农历六月的别称。\n(4)敬慎的样子有萋有～”。\n(5)古同趄”，趑趄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-且"},{"id":"glyph-kai-4e16","script":"kai","character":"世","reading":"shì","description":"shì：(1)一个时代，有时特指三十年～代（a.很多年代；b.好几辈子）。～纪（指一百年）。流芳百～。\n(2)一辈一辈相传的～袭。～家（a.封建社会中门第高，世代做官的人家；b.《史记》中诸侯的传记）。\n(3)人间，以与天上相区别～上。～俗（a.流俗；b.非宗教的）。～故（a.处事待人圆滑，故”读轻声；b.处世经验）。～态炎凉。\n(4)自然界和人类社会一切事物的总和；全地球、人间或宇宙；宇宙的一部分～界。举～瞩目。公之于～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-世"},{"id":"glyph-kai-4e18","script":"kai","character":"丘","reading":"qiū","description":"qiū：(1)小土山土～。沙～。～陵。～壑。\n(2)像小土山凸起的～疹。\n(3)坟墓～墓（大墓）。～垄。\n(4)量词，指用田塍隔开的水田一～十亩大的小田。\n(5)众人聚居的地方～民（乡民，邑民）。\n(6)用砖石封闭有尸体的棺材。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丘"},{"id":"glyph-kai-4e19","script":"kai","character":"丙","reading":"bǐng","description":"bǐng：(1)天干的第三位，用作顺序第三的代称。\n(2)火的代称（五行中丙”、丁”属火）付～（把信件等烧掉）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丙"},{"id":"glyph-kai-4e1a","script":"kai","character":"业","reading":"yè","description":"版,大版\n古代覆在悬挂钟、鼓等乐器架横木上的装饰物,刻如锯齿形,涂以白色\n筑墙版\n古代书册之版\n⒈事情，所从事的工作事～。创～。功～。\n⒉生产或经济部门农～。工～。行～。商～。\n⒊职务，工作岗位职～。就～。转～。\n⒋学习的功课学～。毕～。\n⒌财产产～。家～。\n⒍从事～农。～工。\n⒎已经～已。～经。\n⒏梵语\"羯磨\"的义译，意为\"造作\"。佛教称人的言行、思念为业。分身～、口～、意～，统称三～。又分善与恶，一般都指恶～。\n①高大健壮的样子四牡～ ～。\n②担心害怕的样子兢兢～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-业"},{"id":"glyph-kai-4e1b","script":"kai","character":"丛","reading":"cóng","description":"许多事物凑在一起\n众多;繁杂\n①聚集～集、杂草～生。\n②一簇簇的草木草～、花～。\n③泛指聚集在一起的人或物～书、人～。\n④姓。\n【丛刊】见【丛书】。\n【丛葬】很多尸体合埋的方式，也指这样的坟墓。\n【丛冢】乱葬在一处的许多坟墓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丛"},{"id":"glyph-kai-4e1c","script":"kai","character":"东","reading":"dōng","description":"方位名，太阳升起的一方，与西相对。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-4e1d","script":"kai","character":"丝","reading":"sī","description":"⒈蚕吐出的纤维。它是绸、缎等的原料新～。\n⒉像丝的东西蛛～。铁～。肉～儿。\n⒊细微，极少，细致一～不苟。～毫不差。～ ～入扣。\n⒋计量单位十～为一毫。百～为一厘。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丝"},{"id":"glyph-kai-4e22","script":"kai","character":"丢","reading":"diu1；diū","description":"diū：(1)失去，遗落～失。～人。～盔卸甲。\n(2)放下，抛开～弃。～卒保车（jū）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丢"},{"id":"glyph-kai-4e24","script":"kai","character":"两","reading":"liǎng","description":"双。用于鞋娄\n通辆”。车一乘\n武王戎车三\n⒈数目字\n④新的度量衡单位前，一般用\"两\"～米。～吨。\n⑤形容词前做状语，只能用\"两\"不能用\"二\"势不～立。\n两liàng 1.量词。用于车辆。 2.借指车。 3.容纳一辆车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-两"},{"id":"glyph-kai-4e25","script":"kai","character":"严","reading":"yán","description":"严厉;严肃\n⒈紧密，没有缝隙～密。将瓶口封～。\n⒉认真，不放松～格要求。～厉惩办。～于律己。〈转义〉父亲家～。\n⒊猛烈，厉害～风。～寒。\n⒋急，极其重大的，紧急措施事～。～重。戒～。解～。\n严yǎn 1.庄严貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-严"},{"id":"glyph-kai-4e27","script":"kai","character":"丧","reading":"sàng","description":"⒈失掉，死亡～失。～胆。～命。\n①事情进行不顺利而情绪低落垂头～气。\n②迷信者所谓\"不吉利\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丧"},{"id":"glyph-kai-4e2a","script":"kai","character":"个","reading":"gè","description":"通用个体量词,表示单独的人或物\n字亦作箇”\n俗又作個”\n用于没有专用量词的事物。如一个人;一个影子\n也可用于某些有专用量词的事物\n⒈单，独～人。～别。～体。\n⒉量词洗了～澡。两～苹果。三～月。竹竿万～。\n⒊此，这～中。～样。\n⒋〈表〉动作行为打他～落花流水。\n⒌〈表〉身材或物体的大小瘦～儿。包子～儿不小。\n⒍〈表〉程度或持续笑～不停。讲～没完。\n⒎语气助词。无义明儿～。\n个gàn 1.古代射礼用的箭靶两旁上下伸出的部分，又叫舌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-个"},{"id":"glyph-kai-4e2b","script":"kai","character":"丫","reading":"yā","description":"yā：(1)分杈的树～。～杈。\n(2)像树枝的分杈～头（ａ．古代女孩子头上梳双髻，如树丫杈，因以称女孩子；ｂ．指受役使的女孩子，亦称丫鬟”。头”、鬟”均读轻声）。脚～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丫"},{"id":"glyph-kai-4e2d","script":"kai","character":"中","reading":"zhōng；zhòng","description":"zhōng：中间，内部；居中。zhòng：正对上，受到或达到，如命中、中选、中毒。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-4e30","script":"kai","character":"丰","reading":"fēng","description":"中国古代礼器,形状像豆,用以承酒觯\n蒲草\n地名\n周国都名\n秦沛县之丰邑,汉置县\n⒈富，盛，多，大 ～盛。～硕。～富多彩。～衣足食。～功伟绩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丰"},{"id":"glyph-kai-4e32","script":"kai","character":"串","reading":"chuàn","description":"chuàn：(1)多个同类东西连贯在一起～讲。贯～。\n(2)连贯起来的东西～珠。～铃。\n(3)错误地连接～行（háng）。～味。～换。\n(4)互相勾通、勾结～气。～供。～通一气。\n(5)由这里到那里走动～乡。～门儿。\n(6)扮演戏剧角色～演。客～。\n(7)量词，用于连贯起来的东西一～儿葡萄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-串"},{"id":"glyph-kai-4e34","script":"kai","character":"临","reading":"lín","description":"引申为从上监视着\n⒉到，遇到身～其境。双喜～门。～渴掘井。\n⒊将要～走。～别。\n⒋面对，挨着，靠近～战。～街。～危不惧。\n⒌对照着字、画摹仿～帖。～摹。\n⒍〈古〉帝王上朝～朝。～政。\n①到时候，当时事先准备好，免得～时着急。\n②暂时，短期，非经常的～时措施。\n临lìn 1.哭吊死者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-临"},{"id":"glyph-kai-4e38","script":"kai","character":"丸","reading":"wán","description":"wán：(1)小而圆的东西弹（dàn）～。肉～儿。\n(2)专指药丸”～散膏丹。～药。\n(3)量词，用于丸药吃两～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丸"},{"id":"glyph-kai-4e39","script":"kai","character":"丹","reading":"dān","description":"dān：(1)红色～砂（朱砂）。～桂（观赏植物，花为橘红色）。～心碧血（赤诚的忠心，珍贵的热血）。～青。\n(2)依成方制成的颗粒状或粉末状的中药丸散膏～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丹"},{"id":"glyph-kai-4e3a","script":"kai","character":"为","reading":"wéi；wèi","description":"wéi：做，成为，担任；是；被。wèi：替、给；为了；对、向。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-4e3b","script":"kai","character":"主","reading":"zhǔ","description":"zhǔ：(1)权力或财物的所有者，家庭的首脑～人。物～。失～（失掉财物的人）。当家作～。\n(2)旧时臣子称君王，下级称上级，仆人称家主君～。～上。\n(3)对事物的意见或认为应当如何处理，决定～张。～见。～意。～义。\n(4)对事物有决定权力民～。自～。～持。～宰。～权（一个国家的独立自主的权力）。\n(5)最重要的，最基本的～次。～要。～力。～将（jiàng）。\n(6)预示早霞～雨。\n(7)旧时为死人立的牌位木～。神～。\n(8)基督教、伊斯兰教对所信仰的神或本教创始人的称呼。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-主"},{"id":"glyph-kai-4e3d","script":"kai","character":"丽","reading":"lì","description":"通罹”。遭遇;落入\n丽水\n成对◇作俪”\n⒈漂亮，好看～人。太美～。非常壮～。风和日～。\n⒉附着附～。\n⒊见likz。\n丽lǐ 1.数目。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丽"},{"id":"glyph-kai-4e3e","script":"kai","character":"举","reading":"jǔ；jv","description":"拿起;提起\n飞,飞起;飘动\n⒈抬起，向上托～头。～手。～枪。～案齐眉。〈引〉\n①行动，动作～动。创～。一～成名。\n②发起，兴办～义。～办工厂。\n⒉提出～例。列～。\n⒊推选，推荐推～。选～。\n⒋全～国欢腾。～世无双。\n⒌揭发检～。\n①点火。\n②生火做饭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-举"},{"id":"glyph-kai-4e43","script":"kai","character":"乃","reading":"nǎi","description":"nǎi：(1)才今～得之。断其喉，尽其肉，～去”。\n(2)是，为～大丈夫也。\n(3)竟～至如此。\n(4)于是，就因山势高峻，～在山腰休息片时”。\n(5)你，你的～父。～兄。家祭无忘告～翁”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乃"},{"id":"glyph-kai-4e45","script":"kai","character":"久","reading":"jiǔ","description":"jiǔ：(1)时间长～远。～经。～已。～违（客套话，好久没见）。～仰（初次见面客套话，仰慕已久）。～别重逢。～而～之。\n(2)时间的长短住多～？三年之～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-久"},{"id":"glyph-kai-4e48","script":"kai","character":"么","reading":"me；yāo；ma","description":"yāo：同幺”。\nm：同吗3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-么"},{"id":"glyph-kai-4e49","script":"kai","character":"义","reading":"yì","description":"义不杀少。\n情谊\n⒈公正合宜的道德、道理或行为正～。～愤填膺。～正辞严。见～勇为。多行不～，必自毙。\n⒉意思，含意意～。字～。释～。望文生～。\n⒊情谊有情有～。\n①应尽的责任尽～务。\n②不拿报酬的～务劳动。\n义yí 1.仪容;状貌。 2.仪制;法度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-义"},{"id":"glyph-kai-4e4b","script":"kai","character":"之","reading":"zhī","description":"zhī：(1)助词，表示领有、连属关系赤子～心。\n(2)助词，表示修饰关系缓兵～计。不速～客。莫逆～交。\n(3)用在主谓结构之间，使成为句子成分大道～行也，天下为公”。\n(4)代词，代替人或事物置～度外。等闲视～。\n(5)代词，这，那～二虫，又何知”。\n(6)虚用，无所指久而久～。\n(7)往，到吾欲～南海”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-之"},{"id":"glyph-kai-4e4c","script":"kai","character":"乌","reading":"wū","description":"古代神话传说太阳中有三足乌,因以乌”为太阳的代称\n刚孵化出的幼蚕\n浅黑色\n身披乌衣,手执耒耜,以率将\n⒉黑色～衣。～云。～烟。\n⒊文言副词。哪，何，怎么土～能神？\n乌yā 1.地名用字。\n乌wù 1.见\"乌拉\"﹑\"乌拉草\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乌"},{"id":"glyph-kai-4e4d","script":"kai","character":"乍","reading":"zhà","description":"zhà：(1)忽然～冷～热。～暧还寒。\n(2)刚，起初新来～到。\n(3)张开，鼓起～着胆子（勉强鼓起勇气）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乍"},{"id":"glyph-kai-4e4e","script":"kai","character":"乎","reading":"hū","description":"hū：(1)文言助词，表示疑问汝识之～（吗）？\n(2)文言叹词陛下与谁取天下～（呀）！\n(3)文言介词，相当于”（用在动词或形容词后）在～。无须～。异～寻常。\n(4)古形容词或副词后缀巍巍～。郁郁～。\n(5)古同呼”，呜呼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乎"},{"id":"glyph-kai-4e4f","script":"kai","character":"乏","reading":"fá","description":"fá：(1)缺少～味。贫～。不～其人。\n(2)疲倦～困。～累。疲～。\n(3)无能，无用～气。～煤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乏"},{"id":"glyph-kai-4e50","script":"kai","character":"乐","reading":"lè；yuè","description":"lè：快乐，喜悦；喜欢做某事。yuè：音乐；乐器；姓氏。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-4e52","script":"kai","character":"乒","reading":"pīng","description":"pīng：(1)象声词。\n(2)指乒乓球”～坛。～赛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乒"},{"id":"glyph-kai-4e53","script":"kai","character":"乓","reading":"pāng","description":"pāng：象声词，形容枪声、关门声、东西砸破声等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乓"},{"id":"glyph-kai-4e54","script":"kai","character":"乔","reading":"qiáo","description":"高耸。多用以形容树木\n詈词。宋元以后,曲中用乔者甚多,常随文为释,含有坏、窝囊、糊涂、狡猾、怯懦无用等贬义。形容某种恶劣的表现\n⒉假、伪～装。～妆打扮。\n乔jiāo 1.骄横放纵。\n乔jiǎo 1.见\"乔诘\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乔"},{"id":"glyph-kai-4e56","script":"kai","character":"乖","reading":"guāi","description":"guāi：(1)不顺，不和谐～舛（谬误）。～谬。～戾（性情、言语、行为别扭，不合情理）。～僻（怪僻）。～张（怪僻，不讲情理）。出～露丑。\n(2)机灵，伶俐（多指小孩听话）～～。～巧。卖～。～觉（jué）。～顺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乖"},{"id":"glyph-kai-4e58","script":"kai","character":"乘","reading":"chéng；shèng","description":"chéng：(1)骑，坐～马。～车。～客。～警。\n(2)趁着，就着～便。～机（趁着机会）。～势。～兴（xìng）。因利～便。\n(3)算术中指一个数使另一个数变成若干倍～法。～幂（mì）。～数。\n(4)佛教的教派或教法大～。小～。上～。下～。\n(5)姓。\nshèng：(1)古代称兵车，四马一车为一乘～舆。千～之国。\n(2)古代称四为乘～矢。～壶。以～韦先牛十二犒师”。\n(3)中国春秋时晋国的史书称乘”，后通称一般的史书史～。野～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乘"},{"id":"glyph-kai-4e59","script":"kai","character":"乙","reading":"yǐ","description":"yǐ：(1)天干的第二位，用于作顺序第二的代称。\n(2)指代一方甲方～方。～型脑炎。\n(3)中国古代乐谱的记音符号，相当于简谱7”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乙"},{"id":"glyph-kai-4e5d","script":"kai","character":"九","reading":"jiǔ","description":"jiǔ：(1)数目，八加一（在钞票和单据上常用大写玖”代）～归。\n(2)泛指多次或多数～死一生。～霄云外。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-九"},{"id":"glyph-kai-4e5e","script":"kai","character":"乞","reading":"qǐ","description":"qǐ：(1)向人讨、要、求～求。～丐。～灵（向神佛求助）。～怜。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乞"},{"id":"glyph-kai-4e5f","script":"kai","character":"也","reading":"yě","description":"yě：(1)副词，表示同样、并行的意思你去，我～去。\n(2)在否定句里表示语气的加强一点儿～不错。\n(3)在复句中表转折意虽然你不说，我～能猜个八九不离十。\n(4)文言语气助词（a.表判断；b.表疑问；c.表停顿；d.形容词尾）。\n(5)表示容忍或承认某种情况～罢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-也"},{"id":"glyph-kai-4e60","script":"kai","character":"习","reading":"xí","description":"反覆练习,钻研\n⒈鸟屡次拍着翅膀飞鹰乃学～。\n⒉反复练，反复学，学后再温熟练～。复～。学～。自～。温～。\n⒊通晓，熟悉～地形。～水性。\n⒋长期反复地做，逐渐养成的不自觉的活动～惯。积～。恶～。相沿成～。〈引〉常常地～见。～闻。\n①鸟飞来飞去～ ～笼中鸟。\n②形容微风吹拂凉风～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-习"},{"id":"glyph-kai-4e61","script":"kai","character":"乡","reading":"xiāng","description":"乡”假借为行政区域名\n唐、宋至今指县以下的行政区划。所辖规模历代不\n⒈城市以外的区域，多指农村～间。～村。\n⒉世代所居住的地方或原籍家～。离～。老～。回～。\n⒋政府组织的基层单位，属县、市或区领导。\n乡xiàng 1.窗户。 2.方向;方位。 3.面向，朝着。 4.去，前往。 5.趋向。 6.向往;景仰。 7.偏向，偏爱。 8.从前，原先。 9.面临，将要。参见\"乡迩\"﹑\"乡晨\n\"。 10.介词。表示动作的方向﹑对象等。 11.连词。表示假设。相当于\"如果\"﹑\"假使\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乡"},{"id":"glyph-kai-4e66","script":"kai","character":"书","reading":"shū","description":"乃丹书帛曰陈胜王”,置人所罾鱼\n⒈写，记载～写。奋笔疾～。大～特～。\n⒉文字读其～。读～破万卷。\n⒊信家～。来～已收。\n⒋文件证～。决心～。倡议～。\n⒌装订成册的著作～籍。著～立说。\n⒍字体楷～。行～。草～。\n⒏称某些曲艺说～。鼓～。\n①汉字的书写法则。\n②汉字的书写艺术，也省称\"书\"～画展览。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-书"},{"id":"glyph-kai-4e70","script":"kai","character":"买","reading":"mǎi","description":"雇,租\n⒈用货币换东西，跟\"卖\"相反购～。～轿车。～飞机。〈引〉用钱财或其它手段取得～通。\n①采购货物的人。\n②殖民地、半殖民地国家中，为外国资本家服务，经营银行、工矿、运输、商品等业务的中间人或经纪人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-买"},{"id":"glyph-kai-4e71","script":"kai","character":"乱","reading":"luàn","description":"治理\n扰乱;打乱;使乱\n淫乱,\n⒈无秩序，无条理纷～。杂～。～七八糟。\n⒉骚扰，战争动～。叛～。扰～。兵～。\n⒊混淆以假～真。\n⒋任意，随便～说～动。\n⒌男女关系不正常淫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乱"},{"id":"glyph-kai-4e73","script":"kai","character":"乳","reading":"rǔ","description":"rǔ：(1)分泌奶的器官～房（亦称乳”、奶子”）。～峰。～罩。\n(2)乳房中分泌出来的白色甜汁～汁（亦称奶”）。哺～。～母（奶妈）。～臭（xiù）未干（对年幼人表示轻蔑）。\n(3)像乳汁的东西豆～。～胶。～腐（亦称腐乳”）。\n(4)像乳头的东西钟～（钟上可敲打的突出物）。钟～石。\n(5)生，生殖孳～。\n(6)初生的、幼小的～燕。～牙。～名（小名）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乳"},{"id":"glyph-kai-4e7e","script":"kai","character":"乾","reading":"qián；gān","description":"qián：(1)八卦之一，代表天～坤（坤”，代表地）。\n(2)旧时称男性的～造。～宅。\n坤；\ngān：见干1”⑨～??。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乾"},{"id":"glyph-kai-4e86","script":"kai","character":"了","reading":"le；liǎo","description":"le：助词，表示动作完成或情况变化。liǎo：完结；明白，如了结、了解。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-4e88","script":"kai","character":"予","reading":"yǔ；yú","description":"yú：同余”，我～智自雄（自夸聪明，妄自夸大）。～取～求（原指从我这里取，从我这里求；后指任意索取）。\n夺；取；\nyǔ：给与～以。赐～。赋～。给～。生杀～夺（亦作生杀与夺”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-予"},{"id":"glyph-kai-4e89","script":"kai","character":"争","reading":"zhēng","description":"zhēng：(1)力求获得，互不相让～夺。竞～。～长论短。\n(2)力求实现～取。～气。～胜。\n(3)方言，差，欠总数还～多少？\n(4)怎么，如何（多见于诗、词、曲）～不。～知。～奈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-争"},{"id":"glyph-kai-4e8b","script":"kai","character":"事","reading":"shì","description":"shì：(1)自然界和社会中的现象和活动～情。～件。～业。\n(2)变故～故（出于某种原因而发生的不幸事情，如工作中的死伤等）。～端。\n(3)职业谋～（指找职业）。\n(4)关系和责任你走吧，没你的～了。\n(5)办法光着急也不是～儿，还得另找出路。\n(6)做，治不～生产。无所～事。\n(7)服侍～父母。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-事"},{"id":"glyph-kai-4e8c","script":"kai","character":"二","reading":"èr","description":"èr：(1)数名一加一（在钞票和单据上常用大写贰”代）。\n(2)双，比独一无～。\n(3)两样，别的～话。不～价。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-二"},{"id":"glyph-kai-4e8e","script":"kai","character":"于","reading":"yú","description":"yú：(1)介词（ａ．在，如生～北京”；ｂ．到，如荣誉归～老师”；ｃ．对，如勤～学习”；ｄ．向，如出～自愿”；ｅ．给，如问道～盲”；ｆ．自，从，如取之～民”；ｇ．表比较，如重～泰山”；ｈ．表被动，如限～水平”）。\n(2)后缀（ａ．在形容词后，如疏～防范”；ｂ．在动词后，如属～未来）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-于"},{"id":"glyph-kai-4e8f","script":"kai","character":"亏","reading":"kuī","description":"损耗,损害\n⒈欠缺，短少～斤少两。自感理～。月满则～。功～一篑。\n⒊亏负，对不起不做～心事。他不会～人。\n⒋幸而，多亏幸～。这件事～你帮忙。\n⒌〈表〉讥讽～你干得出来！\n⒍毁坏，损害不～不崩。～败风俗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亏"},{"id":"glyph-kai-4e91","script":"kai","character":"云","reading":"yún","description":"由微小水滴或冰晶组成、漂浮在大气中的云。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-4e92","script":"kai","character":"互","reading":"hù","description":"hù：彼此～相。～助。～利。～生。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-互"},{"id":"glyph-kai-4e94","script":"kai","character":"五","reading":"wǔ","description":"wǔ：(1)数名，四加一（在钞票和单据上常用大写伍”代）～彩。～官。～谷。～金。～代（中国朝代名，后梁、后唐、后晋、后汉、后周先后在中原建立政权的时期）。～帝（中国传说中的五个帝王，通常指黄帝、颛顼、帝喾、唐尧、虞舜）。～毒（指蝎、蛇、蜈蚣、壁虎、蟾蜍）。～行（指金、木、水、火、土）。～岭（指越城岭，都庞岭，萌渚岭、骑田岭、大庾岭）。～岳（指东岳泰山、西岳华山、南岳衡山、北岳恒山和中岳嵩山，是中国历史上五大名山）。～脏（指心、肝、脾、肺、肾）。\n(2)中国古代乐谱的记音符号，相当于简谱6”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-五"},{"id":"glyph-kai-4e95","script":"kai","character":"井","reading":"jǐng","description":"jǐng：(1)人工挖成的能取出水的深洞。水～。临渴掘～。\n(2)形状像井的天～。油～。\n(3)整齐，有秩序～然。～～有条。\n(4)星名，二十八宿之一。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-井"},{"id":"glyph-kai-4e9a","script":"kai","character":"亚","reading":"yà","description":"次;次于。表示时间或空间的先后\n⒈次，第二的～热带。～军。\n⒉较差我不～于他。\n⒊〈外〉亚洲，全称\"亚细亚洲\"，世界七大洲之一。\n亚wù 1.厌恶，憎恶。\n亚yā 1.象声词。 2.助词。犹阿，多用在亲属称呼前，无义。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亚"},{"id":"glyph-kai-4e9b","script":"kai","character":"些","reading":"xiē；suò","description":"xiē：(1)表示不定的数量一～。某～。～微。～许。\n(2)用在形容词后表示比较的程度病轻～了。\nsuò：《楚词》中的句末助词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-些"},{"id":"glyph-kai-4ea1","script":"kai","character":"亡","reading":"wáng；wú","description":"wáng：(1)逃逃～。流～。\n(2)失去～佚。～羊补牢。\n(3)死伤～。死～。\n(4)灭灭～。～国奴。救～。兴～。\n灭；殁；卒；\n兴；存；\nwú：古同无”，没有。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亡"},{"id":"glyph-kai-4ea2","script":"kai","character":"亢","reading":"kàng","description":"kàng：(1)高，高傲高～。不～不卑。\n(2)极度，非常～旱。～奋。\n(3)抗，匹敌～礼。～衡。\n(4)星名，二十八宿之一。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亢"},{"id":"glyph-kai-4ea4","script":"kai","character":"交","reading":"jiāo","description":"jiāo：(1)付托，付给～活儿。～卷。～差。\n(2)相错，接合～点。～界。～错。～相。～辉。～响乐。\n(3)互相来往联系～流。～易。～涉。\n(4)与人相友好～朋友。～契。\n(5)一齐，同时～并。～作。风雨～加。\n(6)两性和合性～。杂～。\n(7)同跤”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-交"},{"id":"glyph-kai-4ea5","script":"kai","character":"亥","reading":"hài","description":"hài：(1)地支的末一位，属猪。\n(2)用于计时～时（晚九点至十一点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亥"},{"id":"glyph-kai-4ea6","script":"kai","character":"亦","reading":"yì","description":"yì：(1)副词，也，表示同样、也是～无不可。～步～趋。\n(2)又先君何罪？其嗣～何罪？”\n(3)不过，只是王～不好土也，何患无士？”\n(4)表示加强或委婉的语气呜呼，～盛矣哉！”学而时习之，不～说乎？”\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亦"},{"id":"glyph-kai-4ea7","script":"kai","character":"产","reading":"chǎn","description":"出产\n①人或动物的幼体从母体中分离出来～卵。\n②制造；生产国～、减～。\n③出产～粮。\n④产品；物产矿～、土特～。\n⑤产业；财～、遗～。\n【产卵回游】见【生殖回游】。\n【产卵器】〈生〉昆虫雌虫的外生殖器官，由腹部后端几节的附肢变成。有各种形状，膜翅目的多呈针状；麦叶蜂的呈扁形、锯状。\n【产品】生产出来的物品；劳动产品的简称这种汽车是我们厂的～。\n【产褥热】〈医〉产妇在临产过程中和产后10天内，因链球菌从生殖器官侵入体内而引起的一种疾病。症状是持续发高烧，下腹痛，阴道流脓血，头痛，呕吐等。\n【产业革命】\n①见【工业革命】。\n②因国民经济各部门广泛地采用新技术，从而引起的经济发展和产业结构的根本变革。\n【产业工人】指在大工厂、矿山、交通运输等部门从事集体生产劳动的工人。\n【产业后备军】'现役劳动军'的对称。资本主义社会中处于失业和半失业状态的相对过剩人口。是资本家获得廉价劳动力、发展资本主义大工业的主要条件。\n【产业军】从事现代化生产的有组织有纪律的劳动者队伍。资本主义社会的产业军是资产阶级组织的。由被剥削被压迫的雇佣劳动者组成。社会主义社会的产业军与资本主义根\n本不同，它是由作为国家主人的劳动者组成的，摆脱了被剥削被压迫的地位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-产"},{"id":"glyph-kai-4ea9","script":"kai","character":"亩","reading":"mǔ","description":"田垄","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亩"},{"id":"glyph-kai-4eab","script":"kai","character":"享","reading":"xiǎng","description":"xiǎng：(1)受用～福。～乐。～誉。～年（敬辞，享有的年岁，对人或朝代而言）。～受。～用。～有。～国（帝王在位年数）。安～。分～。\n(2)贡献（指把祭品，珍品献给祖先、神明或天子、侯王），上供～堂。～殿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-享"},{"id":"glyph-kai-4eac","script":"kai","character":"京","reading":"jīng","description":"jīng：(1)国都（现特指中国首都北京）～城。～都。～华（因京都是文物、人才汇集的地方，所以称京都为京华”）。～畿（国都和国都附近的地方）。～剧。～师（首都的旧称）。～绣。～菜。\n(2)大。\n(3)古代数名，指一千万，亦指一亿兆。\n(4)中国少数民族，主要分布于广西壮族自治区～族。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-京"},{"id":"glyph-kai-4ead","script":"kai","character":"亭","reading":"tíng","description":"tíng：(1)有顶无墙，供休息用的建筑物，多建筑在路旁或花园里；凉～。牡丹～。\n(2)建筑得比较简单的小房子书～。邮～。岗～。\n(3)适中，均匀～匀。\n(4)正，当～午（正午，中午）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亭"},{"id":"glyph-kai-4eae","script":"kai","character":"亮","reading":"liàng","description":"liàng：(1)明，有光天～了，敞～。明～。豁～。～光。～度。\n(2)光线屋子里一点～儿也没有。\n(3)明摆出来，显露，显示～相。\n(4)明朗，清楚心里～了。\n(5)声音响洪～。响～。\n(6)使声音响～开嗓子唱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亮"},{"id":"glyph-kai-4eb2","script":"kai","character":"亲","reading":"qīn","description":"我有亲父母。\n亲密。与疏”相对\n王无亲\n⒈父母双～。养～。\n⒉血统最近或夫妻关系的～姐妹。～人。\n⒊婚姻～事。\n⒌有血统或婚姻关系的～戚。～朋。～表姑。\n⒍感情好，关系密切～密。～近。～如一家。\n⒎用嘴唇接触，表示喜爱～一～孩子。\n⒏本身，自己的～自。～身。～眼见到。～笔所写。事必躬～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亲"},{"id":"glyph-kai-4eba","script":"kai","character":"人","reading":"rén","description":"rén：(1)由类人猿进化而成的能制造和使用工具进行劳动、并能运用语言进行交际的动物～类。\n(2)别人，他人～为刀俎，我为鱼肉”。待～热诚。\n(3)人的品质、性情、名誉丢～，文如其～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-人"},{"id":"glyph-kai-4ebf","script":"kai","character":"亿","reading":"yì","description":"安宁;安定\n极多;极大","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亿"},{"id":"glyph-kai-4ec0","script":"kai","character":"什","reading":"shí；shén","description":"shí：(1)十（多用于分数或倍数）～百（十倍和百）。～一（十分之一）。～袭珍藏（形容极其珍重地收藏物品）。\n(2)各种的，各样的～锦（各种各样东西凑成的食品）。～物。\n(3)诗篇篇～。雅～。\nshén：〔～么〕ａ．代词，表示疑问，如～～人？”ｂ．代词，指不确定的事物，如没～～问题”（么”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-什"},{"id":"glyph-kai-4ec1","script":"kai","character":"仁","reading":"rén","description":"rén：(1)一种道德范畴，指人与人相互友爱、互助、同情等～义（ａ．仁爱与正义；ｂ．通情达理，性格温顺，能为别人着想）。～爱。～政。～人志士（仁爱有节操的人）。～义礼智（儒家的伦理思想）。～至义尽。一视同～（同样看待，不分厚薄）。\n(2)果核的最内部分或其他硬壳中可以吃的部分核桃～儿。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仁"},{"id":"glyph-kai-4ec5","script":"kai","character":"仅","reading":"jǐn","description":"仅然后得兔。\n⒈只，不过～供参考。她不～自己学习好，还肯辅助同学学习。～ ～一点小事。没必要生气。\n⒉见jǐn。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仅"},{"id":"glyph-kai-4ec6","script":"kai","character":"仆","reading":"pú；pū","description":"pū：向前跌倒～倒。前～后继。\n奴；\n主；\n（僿）\npú：(1)被人雇佣差遣服务的人，与主”相对～人。～从。\n(2)旧谦称我”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仆"},{"id":"glyph-kai-4ec7","script":"kai","character":"仇","reading":"chóu；qiú","description":"chóu：深切的怨恨～敌。～恨。～视。疾恶如～。同～敌忾（全体一致痛恨敌人）。\n恩；\nqiú：(1)古同逑”，匹配。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仇"},{"id":"glyph-kai-4eca","script":"kai","character":"今","reading":"jīn","description":"jīn：现在～天。～生。～世。～番（这次）。古为～用。～是昨非。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-今"},{"id":"glyph-kai-4ecb","script":"kai","character":"介","reading":"jiè","description":"jiè：(1)在两者中间～于两者之间。～词（用在名词、代词之前，合起来表示地点、时间、方向、方式等关系的词，如从”、向”、在”、以”、对于”等）。～入。\n(2)这样，这么像煞有～事（好像真有这么回事似的，多指大模大样，好像有什么了不起）。\n(3)放在心里～意。～怀。\n(4)耿直耿～。\n(5)甲～胄。～壳。\n(6)个（用于人）一～书生。\n(7)大～圭（大玉）。\n(8)传统戏曲脚本里表示情态动作的词笑～。饮酒～。\n(9)助～寿。\n(10)姓。\n(11)古同芥”，芥菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-介"},{"id":"glyph-kai-4ecd","script":"kai","character":"仍","reading":"réng","description":"réng：(1)依然，还，照旧～须努力。～然。～旧。\n(2)因袭，沿袭一～其旧。\n(3)频繁，重复频～。～世（一代又一代，累世）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仍"},{"id":"glyph-kai-4ece","script":"kai","character":"从","reading":"cóng","description":"顺从;依从\n①跟着跟～。\n②顺应；听从～命。\n③从事；参与～军。\n④采取某种方式或态度～宽处理、～略。\n⑤跟随的人随～。\n⑥从属的；次要的主～关系、～犯。\n⑧提示空间和时间的起点～北京到南京、～二月到三月。\n⑨提示经过的地方、处所～门外走过。\n【从长计议】把时间放长些，多加考虑和商量。即不急于作出决定。\n【从犯】我国刑法关于共同犯罪人的一种分类。指在共同犯罪中起次要或辅助作用的人。对于从犯，应当比照主犯从轻、减轻或免除处罚。\n【从谏如流】旧时用以形容君王乐于听取臣属的劝谏，接受其意见。\nfamousnovel是个定语从句，由who引导，修饰man。\n【从军】参军；当兵。\n【从良】指妓女不再卖身而嫁人。\n【从容】\n①镇定，不慌乱举止～。\n②宽裕时间～。\n【从容不迫】不慌不忙，镇定自若。\n【从容自如】不慌不忙，神态沉着自然。\n【从善如流】形容能很快地听取好意见或善意的规劝。\n【从属关系】两个概念之间一个概念的外延包含另一个概念全部外延的关系。如'工业'与'轻工业'。\n【从征】随军出征。\n从zōng 1.后多作\"踪\"。踪迹。\n从sǒng 1.通\"耸\"。 2.通\"怂\"。参见\"从容\"﹑\"从谀\"。\n从zòng 1.直。南北曰从，东西曰横。 2.合纵。 3.放纵。 4.纵然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-从"},{"id":"glyph-kai-4ed1","script":"kai","character":"仑","reading":"lún","description":"自我反省检讨\n见昆仑”\n⒈条理，次序。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仑"},{"id":"glyph-kai-4ed3","script":"kai","character":"仓","reading":"cāng","description":"泛指储藏物资的建筑物\n①收藏谷物的建筑物粮～。\n②姓。\n【仓猝】\n【仓卒】\n【仓促】匆忙时间～。\n【仓皇】\n【仓黄】匆忙而带着慌张～逃离现场。又作苍黄。\n【仓颉】一作苍颉。传说是汉字的创造者，黄帝的史官。可能是古代整理文字的代表人物之一。\n【仓库】专供储存物资的建筑物。\n【仓廪】储存粮食的仓库。\n仓chuàng 1.悲伤。参见\"仓兄\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仓"},{"id":"glyph-kai-4ed4","script":"kai","character":"仔","reading":"zǎi；zī；zǐ","description":"zī：〔～肩〕所担负的职务。\nzǐ：幼小的（多指家畜）～鸡。～猪。\n〔～细〕周密，细致，如办事～～”。\nzǎi：同崽”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仔"},{"id":"glyph-kai-4ed6","script":"kai","character":"他","reading":"tā","description":"tā：(1)称你、我以外的第三人，一般指男性，有时泛指，不分性别～们（可包括男性和女性）。～杀。\n(2)别的，另外的～人。～日。～乡。～山之石，可以攻玉。其～。\n(3)虚指睡～一觉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-他"},{"id":"glyph-kai-4ed7","script":"kai","character":"仗","reading":"zhàng","description":"zhàng：(1)兵器仪～。明火执～。\n(2)拿着兵器～剑。\n(3)战争打～。胜～。\n(4)凭借，依靠倚～。仰～。～恃。～义执言（为了正义说公道话）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仗"},{"id":"glyph-kai-4ed8","script":"kai","character":"付","reading":"fù","description":"fù：(1)交，给支～。托～。～款。～梓（把稿件交付刊印）。～讫。～出。～与。～之一笑。～诸东流。\n(2)量词，指中药（亦作服”）一～药。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-付"},{"id":"glyph-kai-4ed9","script":"kai","character":"仙","reading":"xiān","description":"xiān：(1)神话中称有特殊能力、可以长生不死的人～人。～女。～子。～界。～境（a.仙人居住的地方；b.形容景物美好的地方）。～风道骨。～山琼阁（喻虚无缥缈的美妙幻景）。\n(2)具有高超才能的人诗～。酒～。\n(3)婉称死～去。～逝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仙"},{"id":"glyph-kai-4ee3","script":"kai","character":"代","reading":"dài","description":"dài：(1)替～替。～办。～销。～序。～表。\n(2)历史上划分的时期时～。世～。古～。近～。现～。当（dāng）～。年～。\n(3)世系的辈分下一～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-代"},{"id":"glyph-kai-4ee4","script":"kai","character":"令","reading":"lìng；líng；lǐng","description":"líng：〔～狐〕ａ．古地名，在今山西省临猗县一带；ｂ．复姓。\nlǐng：量词，印刷用的原张平版纸五百张为一令。\nlìng：(1)上级对下级的指示命～。法～。朝（zhāo）～夕改。\n(2)古代官名县～。～尹。尚书～。\n(3)使，使得～人兴奋。\n(4)时节时～。节～。\n(5)美好，善～名。～辰。～闻（好名声）。\n(6)敬辞，用于对方的亲属或有关系的人～尊。～堂。～岳。～郎。～爱。\n(7)短的词调（diào），散曲中不成套的曲（多用于词调、曲调名）小～。如梦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-令"},{"id":"glyph-kai-4ee5","script":"kai","character":"以","reading":"yǐ","description":"yǐ：(1)用，拿，把，将～一当十。～苦为乐。～身作则。～邻为壑。～讹传讹。～往鉴来。\n(2)依然，顺，按照～时启闭。物～类聚。\n(3)因为～人废言。勿～善小而不为。不～物喜，不～己悲。\n(4)在，于（指时日）子厚～元和十四年十一月八日卒，年四十七”。\n(5)目的在于～待时机。～儆效尤。\n(6)文言连词，与而”用法相同梦寐～求。\n(7)用在方位词前，表明时间、方位、方向或数量的界限～前。～内。\n(8)用在动词后，类似词的后缀可～。得～。\n(9)古同已”，已经。\n(10)太，甚不～急乎？\n(11)及，连及富～其邻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-以"},{"id":"glyph-kai-4eea","script":"kai","character":"仪","reading":"yí","description":"法度;礼法\n置此以为法,立此以为仪,将以量度天下之王公大人、卿\n⒈容貌，举止～容。～态。～表。\n⒉按程序进行的礼节～式。司～。\n⒊礼物贺～。谢～。\n⒋准则，法度～则。\n⒌指仪器，供测绘、实验等用的有一定准则的用具经纬～。浑天～。地震～。教学～器。\n⒍〈古〉通\"宜\"。应该。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仪"},{"id":"glyph-kai-4eec","script":"kai","character":"们","reading":"mén","description":"用在代词或指人的名词后面,表示复数。如孩子们\n么”的变音字\n注意名词前有数量词时，后面不加们”，例如不说三个孩子们”\n们men词尾，〈表〉人的复数我～。你～的。老师～。\n们mén 1.词的后缀。用在人称﹑物称代词或指人﹑指物的名词后面，表示复数。 2.词的后缀。用于具体的人名后，表示\"等人\"﹑\"之辈\"。 3.词的后缀。用在指示代词后面\n，相当于\"这么\"﹑\"那么\"的\"么\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-们"},{"id":"glyph-kai-4ef0","script":"kai","character":"仰","reading":"yǎng；áng","description":"yǎng：(1)脸向上，与俯”相对～首。～望。\n(2)敬慕久～。敬～。\n(3)依赖～承。～赖。～仗。～人鼻息。\n(4)旧时公文用语。上行文中用在请、祈、恳”等字之前，表示恭敬；下行文中表示命令～即尊照。\n(5)服下，指服毒～药（服毒药自杀）。～毒。\n(6)姓。\n俯；\náng：古同昂”，情绪高。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仰"},{"id":"glyph-kai-4ef2","script":"kai","character":"仲","reading":"zhòng","description":"zhòng：(1)兄弟排行次序二～兄。～弟。\n(2)在当中的～春（春季的第二个月，即农历二月。仲夏、仲秋、仲冬依此类推）。～裁（居间调停、裁判）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仲"},{"id":"glyph-kai-4ef6","script":"kai","character":"件","reading":"jiàn","description":"jiàn：(1)量词，用于个体事物一～事。\n(2)指可以一一计算的事物零～儿。案～。\n(3)不平常的大事情事～。\n(4)文书证明之类文～。来～。证～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-件"},{"id":"glyph-kai-4ef7","script":"kai","character":"价","reading":"jià；jiè","description":"jiè：旧时称派遣传递东西或传达事情的人走～驰书来诣”。\n（價）\njie：(1)方言，用在否定副词后面加强语气不～。\n(2)副词性词尾震天～响。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-价"},{"id":"glyph-kai-4efb","script":"kai","character":"任","reading":"rèn；rén","description":"rèn：(1)相信，信赖信～。\n(2)使用，给予职务～命。～人唯贤。\n(3)负担，担当担～。～课。\n(4)职务就～。到～。～重道远。\n(5)由着，听凭～凭。～性。～意。～从。～随。听～。放～自流。听之～之。\n(6)不论，无论～何。～人皆知。\n免；\nrén：(1)中国古代女子爵位名。\n(2)中国古代南方的一种民族乐曲。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-任"},{"id":"glyph-kai-4efd","script":"kai","character":"份","reading":"fèn；bīn","description":"fèn：(1)整体里的一部～额。～饭。股～。\n(2)量词指成组、成件的一～儿报纸。\n(3)用在省、县、年、月”后面，表示划分的单位省～。月～。\nbīn：古同彬”，文质兼备。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-份"},{"id":"glyph-kai-4eff","script":"kai","character":"仿","reading":"fǎng","description":"fǎng：(1)效法，照样做～效。～古。～冒。～宋（印刷字体的一种，亦称仿宋体”）。\n(2)依照范本写的字～影。～书。\n(3)相似，好像～像（仿佛相似）。～佛（fú）。二者相～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-仿"},{"id":"glyph-kai-4f01","script":"kai","character":"企","reading":"qǐ","description":"qǐ：(1)踮着脚看，今用为盼望的意思～盼。～足而待。～及（盼望达到，希望赶上）。～图（图谋）。\n(2)开启。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-企"},{"id":"glyph-kai-4f0a","script":"kai","character":"伊","reading":"yī","description":"yī：(1)彼，他，她～说。～人（那个人，多指女性）。\n(2)文言助词下车～始。～谁之力？～于胡底（到什么地步为止，不堪设想的意思）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伊"},{"id":"glyph-kai-4f0d","script":"kai","character":"伍","reading":"wǔ","description":"wǔ：(1)古代军队的编制一～（五人）。\n(2)军队入～。落～（掉队）。\n(3)同伴的人羞与为～。\n(4)五”的大写。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伍"},{"id":"glyph-kai-4f0f","script":"kai","character":"伏","reading":"fú","description":"fú：(1)趴，脸向下，体前屈～卧。～案读书。\n(2)低下去此起彼～。\n(3)屈服，承认错误或受到惩罚～法。～输。～辩（伏罪的供状，亦作伏辨”）。\n(4)使屈服降～。降龙～虎。\n(5)隐藏～兵。埋～。\n(6)农历划分夏季最炎热的三个阶段～日。～旱。～暑。～天。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伏"},{"id":"glyph-kai-4f10","script":"kai","character":"伐","reading":"fá","description":"fá：(1)砍～树。砍～。\n(2)征讨讨～。～罪（征讨有罪的人）。口诛笔～。\n(3)自夸～善（夸自己的好处）。～智。不矜不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伐"},{"id":"glyph-kai-4f11","script":"kai","character":"休","reading":"xiū；xù","description":"xiū：(1)歇息～整。～假。～闲。离～。\n(2)停止～业。\n(3)完结（多指失败或死亡）。\n(4)旧指丈夫把妻子赶回母家，断绝夫妻关系～妻。\n(5)不要～想。～提。\n(6)吉庆，美善，福禄～咎（吉凶）。\n(7)助词，用于语末，与罢”、了”等用法相当归～。\n(8)辞去官职～官。\n戚；\nxù：古同煦”，温暖。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-休"},{"id":"glyph-kai-4f17","script":"kai","character":"众","reading":"zhòng","description":"⒈多，许多～多。～人。～星捧月。\n⒉许多人群～。～怒难犯。～望所归。～志成城。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-众"},{"id":"glyph-kai-4f18","script":"kai","character":"优","reading":"yōu","description":"⒈美好。跟\"劣\"相对～等品。～美别致。～秀教师。～良品质。\n①从容。\n②犹豫不决～柔寡断。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-优"},{"id":"glyph-kai-4f19","script":"kai","character":"伙","reading":"huǒ","description":"同火”。古兵制十人为火,同火的人互称火伴。俗作伙伴,同伴\n合伙;由若干人结成的一群\n群聚;结伴;联合一起干\n一群的人\n伙〈名〉\n伙食。饭食\n⒉联合，共同～办工厂。～同一起∠～经商。\n⒊量词。群一～小孩。五人一～。\n⒋集体所办的餐食起～。搭～。～食团。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伙"},{"id":"glyph-kai-4f1a","script":"kai","character":"会","reading":"huì","description":"⒈聚合，联合～合。聚～。～师。～盟。宴～。\n⒉见面，对话～见。～面。～客。～话。\n⒊理解，懂得～意。能领～。\n⒋能，可能，善于共产主义一定～实现。他～开飞机。不～不懂吧！她能说～道。\n⒌时机机～。逢时遇～。适逢其～。\n⒍短促的时间这～儿。一～儿就来。请等～儿吧。\n⒎付钱～账。茶钱我～过了。\n⒏多数人的集合，或为共同目的所组成的团体纪念～。报告～。商～。学生～。董事～。人民代表大～。\n⒑恰巧，正好～天大雨，道不通。\n⒒见kuài。\n⒈总计。\n①管理与计算财务的工作。\n②担任会计工作的人。。\n会kuò 1.见\"会撮\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-会"},{"id":"glyph-kai-4f1e","script":"kai","character":"伞","reading":"sǎn","description":"特指伞盖。长柄,圆顶,伞面边缘有流苏下垂,也称马伞。古代仪仗的一种,用不同颜色区别品级的高下。知府以上用黄色,知州以下用蓝色\n雨伞;阳伞\n伞形物或降落伞的简称\n⒈挡雨或遮阳光的用具，可张可收雨～。太阳～。\n⒉像伞的东西降落～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伞"},{"id":"glyph-kai-4f1f","script":"kai","character":"伟","reading":"wěi","description":"奇异","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伟"},{"id":"glyph-kai-4f20","script":"kai","character":"传","reading":"chuán；zhuàn","description":"chuán：传递、传播、传授。zhuàn：记述人物生平事迹的文字；某些叙事作品的名称，如传记。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-4f24","script":"kai","character":"伤","reading":"shāng","description":"⒈受到损害、损坏受～。枪～。重～。\n⒉损害，妨碍～害。损～。～点皮肉。无～大局。\n⒊遭受某种致病因素而得病～风。～暑。\n⒋悲哀～心。悲～。\n⒌使用过度以致厌烦这种菜吃～了。\n⒍得罪，诋毁有意中～。出口～人。\n①伤寒杆菌引起的急性传染病。\n②中医学上泛指各种热病或风寒引起的疾病。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伤"},{"id":"glyph-kai-4f26","script":"kai","character":"伦","reading":"lún","description":"条理,顺序\n人伦,人与人之间的道德关系\n⒈类，同类不～不类。超群绝～。\n⒉条理，顺序语无～次。\n⒊比，匹敌～比。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伦"},{"id":"glyph-kai-4f2a","script":"kai","character":"伪","reading":"wěi","description":"人为;矫饰\n伪装;假装\n⒈假，不真实～装。～科学。～劣产品。去～存真。\n⒉诡诈，不诚实奸～。虚～。\n⒊非法的窃取政权而不为人民承认的～总统。～政府。\n伪é 1.通\"讹\"。改变;变化。 2.通\"讹\"。错误;差错。参见\"伪谬\"。 3.通\"吪\"。动。\n伪guì 1.钱币。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伪"},{"id":"glyph-kai-4f2f","script":"kai","character":"伯","reading":"bó；bǎi；bà","description":"bó：(1)兄弟排行次序～仲（指兄弟的次第，喻事物不相上下）。\n(2)父亲的哥哥～～。～父。～母。\n(3)对父辈戚友的尊称老～。世～。\n(4)封建制度五等爵位的第三等～爵。\n(5)旧时对文章、道德足为表率者的尊称海内文章～”。\n(6)姓。\nbǎi：〔大～子〕丈夫的大哥。\nbà：古同霸”，古代诸侯联盟的首领。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伯"},{"id":"glyph-kai-4f30","script":"kai","character":"估","reading":"gū；gù","description":"gū：(1)揣测，大致地推算～计。～价。～一～。\n(2)古同贾”，商人。\ngù：〔～衣〕出售的旧衣服或原料较次、加工较粗的新衣服。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-估"},{"id":"glyph-kai-4f34","script":"kai","character":"伴","reading":"bàn","description":"bàn：(1)同在一起而能互助的人伙～。～侣。\n(2)陪同～随。陪～。～和（hè）。～舞。～奏。～读（古代官名，中国宋代有南北院伴读，负责宗室子弟的教学，辽、金至明代，皆为亲王府官）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伴"},{"id":"glyph-kai-4f36","script":"kai","character":"伶","reading":"líng","description":"líng：旧时称以演戏为职业的人优～。名～。～官（古代乐官）。\n〔～仃〕孤独。\n〔～俐〕聪明；灵活。\n〔～俜〕孤独的样子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伶"},{"id":"glyph-kai-4f38","script":"kai","character":"伸","reading":"shēn","description":"shēn：(1)舒展开～直。～手（ａ．伸出手；ｂ．喻向别人或上级要东西、荣誉、照顾；ｃ．指插手）。～张（扩大，如～张正义”）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伸"},{"id":"glyph-kai-4f3a","script":"kai","character":"伺","reading":"sì；cì","description":"sì：观察，侦候窥～。～机。～察。～应（yìng）（等候响应）。\ncì：〔～候〕ａ．在人身边供使唤；ｂ．照料饮食起居（候”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-伺"},{"id":"glyph-kai-4f3c","script":"kai","character":"似","reading":"sì；shì","description":"sì：(1)相类，像相（xiāng）～。类～。～是而非。\n(2)好像，表示不确定～乎。～应如此。\n(3)表示比较，有超过的意思一个高～一个。\nshì：〔～的〕跟某种情况或事物相似，如他乐得什么～～”。亦作是的”（的”均读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-似"},{"id":"glyph-kai-4f43","script":"kai","character":"佃","reading":"diàn；tián","description":"diàn：向地主或官府租种土地的农民～户。～农。～客（晋代世家豪强荫庇下的一种依附农民）。～东。\ntián：(1)耕作。\n(2)古同畋”，打猎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佃"},{"id":"glyph-kai-4f46","script":"kai","character":"但","reading":"dàn","description":"dàn：(1)只，仅，只是～愿如此。～凡（凡是，只要是）。～分（只要）。\n(2)不过，可是工作虽辛苦，～没有叫苦的。\n(3)徒然何～远走，亡匿于幕北苦寒无水草之地为？”\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-但"},{"id":"glyph-kai-4f4d","script":"kai","character":"位","reading":"wèi","description":"wèi：(1)所处的地方座～。部～。～置（ａ．所在或所占的地方；ｂ．地位）。～于。\n(2)职务的高低地～。职～。名～。\n(3)特指君主的地位即～。篡～。\n(4)一个数中每个数码所占的位置个～。百～数。\n(5)量词，常用于人，表尊重诸～。各～。几～客人。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-位"},{"id":"glyph-kai-4f4e","script":"kai","character":"低","reading":"dī","description":"dī：(1)地势或位置在一般标准或平均程度之下，与高”相对～空。～地。～谷。～潮。～沉（ａ．云层厚而低；ｂ．声音低；ｃ．情绪低落）。\n(2)矮短身材～矮。\n(3)细小，沉重～微（ａ．声音细小；ｂ．身份或地位低）。～吟。\n(4)程度差～级。～能。眼高手～。\n(5)卑贱～贱。～首下心。\n(6)等级在下的～俗。～档商品。\n(7)价钱少～价出售。\n(8)俯，头向下垂～头从事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-低"},{"id":"glyph-kai-4f4f","script":"kai","character":"住","reading":"zhù","description":"zhù：(1)长期居留或短暂歇息居～。～宿。～房。～户。\n(2)停，止，歇下～手。雨～了。\n(3)动词的补语（ａ．表示稳当或牢固，如站～”；ｂ．表示停顿或静止，如他愣～了”。ｃ．与得”或不”连用，表示力量够得上，如支持不～了”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-住"},{"id":"glyph-kai-4f50","script":"kai","character":"佐","reading":"zuǒ","description":"zuǒ：(1)辅助，帮助～证（证据）。～餐。\n(2)处于辅助地位的人僚～。\n(3)劝～食。～酒（ａ．陪伴喝酒；ｂ．就着菜肴把酒喝下去）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佐"},{"id":"glyph-kai-4f51","script":"kai","character":"佑","reading":"yòu","description":"yòu：帮助～护。～助。保～。庇～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佑"},{"id":"glyph-kai-4f53","script":"kai","character":"体","reading":"tǐ","description":"⒈人或动物的全身人～。机～。身～。～重。～温。\n⒊事物的本身或全部物～。全～。个～。整～。总～。\n⒋形态气～。立～。\n⒌形式，规格字～。得～。\n⒍文章的体裁骚～。骈文～。古诗～。\n⒎实质，根本，主要的实～。本～。主～。\n⒏指体制国～。政～。\n①身分有失～面。\n②光荣，光彩显得～面。\n③漂亮，好看她穿着很～面。\n①家庭成员个人积蓄的财物。\n②私下的，亲近的～己话。\n体bèn 1.见\"体夫\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-体"},{"id":"glyph-kai-4f55","script":"kai","character":"何","reading":"hé；hē；hè","description":"hé：(1)疑问代词（ａ．什么，如～人？”ｂ．为什么，如～必如此？”ｃ．哪样，怎样，如～不？”～如？”ｄ．哪里，如～往？”ｅ．发表反问，如～乐而不为？”）。\n(2)副词，多么～其壮哉！\n(3)姓。\nhē：古同呵”，谴责。\nhè：古同荷”，担。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-何"},{"id":"glyph-kai-4f59","script":"kai","character":"余","reading":"yú","description":"饱足。足食得饱\n剩下;剩余\n剩下的,多余的\n残留的;\n⒈我，我的。\n⒉剩下的，多出的剩～。节～。多～。有～。～粮。不遗～力。\n⒊遗留，遗存城荒古迹～。\n⒋零数十～天。百～人。五里～。\n⒌后，以外业～。工作之～。\n余yù 1.姓。见\"余且\"。\n余xú 1.见\"余吾\"。\n余tú 1.梼余，山名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-余"},{"id":"glyph-kai-4f5b","script":"kai","character":"佛","reading":"fó；fú；bì；bó","description":"fó：(1)梵语佛陀”，是对佛教创始人释迦牟尼的简称，亦是佛教徒对修行圆满的人的称呼～爷。～像。借花献～。\n(2)指佛教”（世界主要宗教之一）～家。～寺。～老。～经。～龛。～事（佛教徒诵经、祈祷及供奉佛像等活动）。\nfú：古同拂”，违背，违反。\n〔仿～〕见仿”。\nbì：古同弼”，辅弼。\nbó：古同勃”，兴起。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佛"},{"id":"glyph-kai-4f5c","script":"kai","character":"作","reading":"zuò","description":"zuò：(1)起，兴起，现在起振～。枪声大～。\n(2)从事，做工工～。～息。～业。\n(3)举行，进行～别（分别）。～乱。～案。～战。～报告。\n(4)干出，做出，表现出，制造出～恶（è）。～弊。～梗。～祟。～态。～色。～为。～难。～奸犯科（为非作歹，触犯法令）。\n(5)当成，充当～罢。～保。～伐（做媒人）。～壁上观（人家交战，自己站在营垒上看，喻坐观别人成败）。\n(6)创造创～。写～。～曲。～者。\n(7)文艺方面的成品～品。不朽之～。\n(8)同做”。\n(9)旧时手工业制造加工的场所～坊。\n(10)从事某种活动～揖。～弄。～死。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-作"},{"id":"glyph-kai-4f60","script":"kai","character":"你","reading":"nǐ","description":"nǐ：(1)称对方，多称指一个人，有时也指称若干人～厂。～方。\n(2)泛指任何人～死我活。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-你"},{"id":"glyph-kai-4f63","script":"kai","character":"佣","reading":"yòng","description":"佣者笑而应。\n若为佣耕。\n子不佣矣。\n佣chōng 1.均;公平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佣"},{"id":"glyph-kai-4f69","script":"kai","character":"佩","reading":"pèi","description":"pèi：(1)挂，带～带。～戴。～剑。\n(2)古代系在衣带上的玉饰玉～。\n(3)心悦诚服～服。钦～。敬～。可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佩"},{"id":"glyph-kai-4f73","script":"kai","character":"佳","reading":"jiā","description":"jiā：美，好的～美。～妙。～句。～作。～音。～节。～境。～期。～人。～丽（ａ．美丽；ｂ．美女）。～偶。～酿。美酒～肴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-佳"},{"id":"glyph-kai-4f7f","script":"kai","character":"使","reading":"shǐ","description":"shǐ：(1)用～用。～劲。～役。～力。～钱。\n(2)派，差谴～唤。～命。～女。\n(3)让，令，叫迫～。\n(4)假若假～。即～。\n(5)奉命办事的人～者。大～。公～。～馆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-使"},{"id":"glyph-kai-4f84","script":"kai","character":"侄","reading":"zhí","description":"zhí：弟兄的儿子，同辈男性亲友的儿子～儿。～女。叔～。子～辈。～孙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侄"},{"id":"glyph-kai-4f88","script":"kai","character":"侈","reading":"chǐ","description":"chǐ：(1)浪费，用财物过度～糜。奢～。穷奢极～。\n(2)夸大～谈。\n(3)邪行放辟邪～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侈"},{"id":"glyph-kai-4f8b","script":"kai","character":"例","reading":"lì","description":"lì：(1)可以做依据的事物～证。～题。举～。～句。～如。\n(2)规定～外（不按规定的，和一般情况不同的）。体～。凡～。条～。破～。发凡起～。\n(3)按规定的，照成规进行的～会。～假。～行公事。\n(4)调查或统计时指合于某种条件的具有代表性的事情事～。病～。案～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-例"},{"id":"glyph-kai-4f8d","script":"kai","character":"侍","reading":"shì","description":"shì：伺候，在旁边陪着服～。～立。～者（侍奉左右的人）。～从。～读（给帝王讲学的人）。～坐。～役（仆人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侍"},{"id":"glyph-kai-4f9b","script":"kai","character":"供","reading":"gòng；gōng","description":"gōng：准备着东西给需要的人应用～给（jǐ）。～求。～应。～需。～销。提～。～不应求。\n求；\ngòng：(1)奉献～养。～献。～奉。～佛。～职。\n(2)祭祀用的东西～桌。～品。～果。上～。\n(3)被审问时在法庭上述说事实招～。口～。～状。～认。～词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-供"},{"id":"glyph-kai-4f9d","script":"kai","character":"依","reading":"yī","description":"yī：(1)靠，仗赖～靠。～傍（a.依靠；b.摹仿，多指艺术、学问）。～恋。～偎。～存。～附。归～。\n(2)按照～照。～旧。～据。～次。\n(3)顺从，答应～从。～顺。～允。\n(4)亲密的样子有～其士”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-依"},{"id":"glyph-kai-4fa0","script":"kai","character":"侠","reading":"xiá","description":"侠客\n材力绝人,少重然许,喜侠节。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侠"},{"id":"glyph-kai-4fa3","script":"kai","character":"侣","reading":"lǚ；lv","description":"lǚ：(1)伴～伴。伴～。爱～。情～。旧～。\n(2)结为伴侣～鱼虾而友麋鹿”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侣"},{"id":"glyph-kai-4fa5","script":"kai","character":"侥","reading":"yáo；jiao","description":"贪求不止\n引申指希求意外成功或幸免\n侥薄,即浇薄。指民俗浮薄\n僥侥\n南方有焦侥人,长三尺,短之极,从人,尧声。╠","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侥"},{"id":"glyph-kai-4fa6","script":"kai","character":"侦","reading":"zhēn","description":"问,卜问。凭借占卜来寻求预言\n侦察\n探子;间谍\n侦zhēn探伺，暗中察看～探。～察。～查。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侦"},{"id":"glyph-kai-4fa7","script":"kai","character":"侧","reading":"cè","description":"边缘\n向旁边歪斜\n侧弁之俄\n①旁边～面、两～。\n②向一边歪斜～目、～耳细听、～重效果。又见zè。\n【侧锋】〈美〉中国画技法。运笔时笔头向左右倾斜，使笔尖、笔腰、笔根同时发挥作用。兼有粗、细、浓、淡、干、湿等变化。常用于中国画的意笔画。又称偏锋。\n【侧棱】棱柱或棱台的两个侧面的公共边。\n【侧面】\n【侧面积】侧面的面积。\n【侧目】不敢正视，斜着眼睛看。形容害怕而又愤恨～而视。\n【侧线】〈生〉动物身体两侧，排列成直线形的一种构造。某些蛔虫的侧线由外胚层所形成，排泄管由此通过。鱼类及水生两栖类动物的侧线能感觉水流振动及声音。\n【侧芽】生在叶腋、尚未发育成长的枝或花的雏体。又叫腋芽。\n【侧泳】一种游泳姿势。游时侧卧水面，两手臂轮流划水。\n【侧足】、形容因畏惧而不敢对面站立～而立。\n②置足；落脚。\n⒈［侧声］即\"仄声\"，见 \"仄\n厕同。\" 8.藏伏。 9.轻微。 10.汉字笔画中\"点\"的古称。参见\"永字八法\"。 11.通\"恻\"。悲伤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侧"},{"id":"glyph-kai-4fa8","script":"kai","character":"侨","reading":"qiáo","description":"客居异地\n客居国外\n寄居国外的人\n⒈寄居在国外或外乡～居。～寓。\n⒉寄居在国外的人～民。华～。外～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侨"},{"id":"glyph-kai-4fae","script":"kai","character":"侮","reading":"wǔ","description":"wǔ：(1)欺负，轻慢～辱（使对方人格或名誉受到损害，蒙受耻辱）。～蔑（轻视，轻蔑）。欺～。不可～。\n(2)古代奴婢的贱称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侮"},{"id":"glyph-kai-4faf","script":"kai","character":"侯","reading":"hòu；hóu","description":"hóu：(1)封建制度五等爵位的第二等～爵。～门。公～。封～。诸～。\n(2)古代用作士大夫之间的尊称。\n(3)姓。\nhòu：〔闽～〕地名，在中国福建省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侯"},{"id":"glyph-kai-4fb5","script":"kai","character":"侵","reading":"qīn","description":"qīn：(1)（敌人）进入境内，（外来的或有害的事物）进入内部～害。～吞。～略。～染。～蚀。\n(2)渐近～晨。～晓。～早（破晓，天刚亮）。\n(3)古代称荒年五谷不生，谓之大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-侵"},{"id":"glyph-kai-4fbf","script":"kai","character":"便","reading":"biàn；pián","description":"biàn：(1)顺利，没有困难或阻碍～当。～利。～道。～民。\n(2)简单的，礼节上非正式的～宴。～衣。～函（形式比较简便的信件）。简～。～宜。随～（适当地，看事实需要而自行处理事情）。\n(3)便利的时候～中请来信。\n(4)就说了～做。\n(5)排泄屎尿或排泄出来的屎尿大～。～秘。\n即；就；\npián：〔～～〕肚子肥大的样子，如大腹～～”。\n〔～嬖〕封建统治者所亲近宠爱的人。\n〔～佞〕善于用花言巧语讨好的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-便"},{"id":"glyph-kai-4fc3","script":"kai","character":"促","reading":"cù","description":"cù：(1)近，时间紧迫～膝。～席（坐近）。急～。短～。仓～。\n(2)催，推动～使。～进。敦～。督～。催～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-促"},{"id":"glyph-kai-4fc4","script":"kai","character":"俄","reading":"é","description":"é：短时间～尔。～然。～顷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俄"},{"id":"glyph-kai-4fca","script":"kai","character":"俊","reading":"jùn","description":"jùn：(1)才智出众的人～杰。～伟。～彦（才智杰出的人）。～爽。～造（学识造诣很深的人）。\n(2)容貌美丽～俏。～美。～秀。～逸（俊美洒脱，不同凡俗）。英～。\n(3)古同峻”，大。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俊"},{"id":"glyph-kai-4fcf","script":"kai","character":"俏","reading":"qiào；xiào","description":"qiào：(1)相貌美好，漂亮～丽（俊俏美丽）。～媚。～爽。俊～。\n(2)货物的销路好，价格上涨～货。走～。\n(3)烹调时为增加滋味、色泽而加上东西～头（a.烹调时加上的青蒜、香菜、木耳等；b.戏曲、曲艺中引入喜爱的身段、道白或穿插。头”均读轻声）。～点儿香菜。\nxiào：古同肖”，相似。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俏"},{"id":"glyph-kai-4fd0","script":"kai","character":"俐","reading":"lì","description":"lì：〔伶～〕见伶”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俐"},{"id":"glyph-kai-4fd7","script":"kai","character":"俗","reading":"sú","description":"sú：(1)社会上长期形成的风尚、礼节、习惯等～尚。风～。习～。约定～成（指某种事物是由群众通过长期实践而认定形成）。\n(2)大众化的，最通行的，习见的～名。～语。～曲。雅～共赏。\n(3)趣味不高的，令人讨厌的～气。～物。鄙～。粗～。庸～。\n(4)凡世间，相对于仙佛僧道～人。世～。僧～。凡夫～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俗"},{"id":"glyph-kai-4fd8","script":"kai","character":"俘","reading":"fú","description":"fú：(1)打仗时被擒的敌人～虏。战～。遣～。\n(2)打仗时擒住敌人～获。被～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俘"},{"id":"glyph-kai-4fdd","script":"kai","character":"保","reading":"bǎo","description":"bǎo：(1)看守住，护着不让受损害或丧失～卫。～管。～健。～障。～密。明哲～身。朝不～夕（早晨保不住晚上会发生什么情况。形容形势危急）。\n(2)维持原状，使不消失或减弱～持。～洁。～质。～墒。\n(3)负责～证。～荐。～修。～险。确～。担～。\n(4)旧时户口的一种编制，若干甲为一保。\n(5)旧称佣工酒～（酒店服务人员）。佣～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-保"},{"id":"glyph-kai-4fe1","script":"kai","character":"信","reading":"xìn；shēn","description":"xìn：(1)诚实，不欺骗～用。～守。～物。～货。～誓旦旦。\n(2)不怀疑，认为可靠～任。～托。～心。～念。\n(3)崇奉～仰。～徒。\n(4)消息～息。杳无音～。\n(5)函件～件。～笺。～鸽。～访。\n(6)随便，放任～手（随手）。～步（随意走动，散步）。～笔。～意。\n(7)同芯2”。\n(8)姓。\n疑；\nshēn：(1)古同伸”，舒展开。\n(2)古同伸”，表白。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-信"},{"id":"glyph-kai-4fe9","script":"kai","character":"俩","reading":"liǎng；lia","description":"注意俩”后面不再接个”字或其他量词\n⒉见liǎng。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俩"},{"id":"glyph-kai-4fed","script":"kai","character":"俭","reading":"jiǎn","description":"节俭,节省\n⒈节省，不浪费～省。衣着～朴。勤～办一切事业。\n⒉约束，不放纵恭～。\n⒊贫乏，歉收。旧时称青黄不接之时为\"俭月\"，荒年为\"俭岁\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俭"},{"id":"glyph-kai-4fee","script":"kai","character":"修","reading":"xiū","description":"xiū：(1)装饰，使完美～饰。～辞。装～。\n(2)整治，恢复完美～复。～治。～缮（修理）。～浚（修理疏通）。～好。～明（古代指政治清明）。\n(3)剪或削～剪。\n(4)兴建，建造～建。～筑。\n(5)编纂，撰写～书。～史。～纂。\n(6)（学问，品行方面）钻研、学习、锻炼～学。～业。～养。\n(7)长（cháng），高～长。\n(8)信奉宗教的人虔诚地学习教义，并付诸行动～行。～女。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-修"},{"id":"glyph-kai-4fef","script":"kai","character":"俯","reading":"fǔ","description":"fǔ：(1)向下，低头，与仰”相对～身。～视。～瞰。～首。～临。～拾即是。～仰。\n(2)潜伏，卧伏季秋之月蛰虫咸～在内”。\n(3)旧时公文及书信对上级或尊长的敬辞～允。～念。～恤（请求对方体恤）。～察。～顺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俯"},{"id":"glyph-kai-4ff1","script":"kai","character":"俱","reading":"jù；jv","description":"jù：(1)全，都百废～兴。声色～厉。\n(2)一起；在一起～乐部。君与～来。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俱"},{"id":"glyph-kai-4ffa","script":"kai","character":"俺","reading":"ǎn","description":"ǎn：方言，我，我们（不包括听说话的人）～要上学。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-俺"},{"id":"glyph-kai-500d","script":"kai","character":"倍","reading":"bèi","description":"bèi：(1)等于原数的两个加～。事～功半。～道而行（兼程而行）。\n(2)某数的几倍等于用几乘某数二的五～是十。\n(3)更加，非常每逢佳节～思亲”。～加。～儿精神。\n(4)增益焉用亡郑以～邻？”\n(5)古同背”，背弃，背叛。\n(6)古同背”，背诵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倍"},{"id":"glyph-kai-5012","script":"kai","character":"倒","reading":"dǎo；dào","description":"dǎo：(1)竖立的东西躺下来摔～。墙～了。～塌。～台。打～。卧～。\n(2)对调，转移，更换，改换～手。～换。～车。～卖。～仓。～戈。\n正；顺；\ndào：(1)位置上下前后翻转～立。～挂。～影。～置。\n(2)把容器反转或倾斜使里面的东西出来～水。～茶。\n(3)反过来，相反地～行逆施。反攻～算。～贴。\n(4)向后，往后退～退。～车。\n(5)却东西～不坏，就是旧了点。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倒"},{"id":"glyph-kai-5014","script":"kai","character":"倔","reading":"juè；jué","description":"jué：(1)顽强，固执～强（jiàng）。\n(2)古同崛”，突出。\njuè：言语粗直，态度不好那老头真～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倔"},{"id":"glyph-kai-5018","script":"kai","character":"倘","reading":"tǎng；cháng","description":"tǎng：假使，如果～或。～若。～使。～然。\ncháng：同徜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倘"},{"id":"glyph-kai-5019","script":"kai","character":"候","reading":"hòu","description":"hòu：(1)等待等～。～车室。～选人。守～。～补。～场。～审。～诊。\n(2)看望，问好伺～。问～。\n(3)时节时～。气～。～鸟。～虫。\n(4)事物在变化中的情状火～儿。症～。\n(5)古代把五天称为一候”，现气象学上仍沿用～温（每五天的平均温度）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-候"},{"id":"glyph-kai-501a","script":"kai","character":"倚","reading":"yǐ","description":"yǐ：(1)靠着，～靠。～赖。～傍。～托。～重。\n(2)仗恃～势。～恃。～仗。\n(3)偏，歪不偏不～。\n(4)随着，和着使慎夫人鼓瑟，上自～瑟而歌”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倚"},{"id":"glyph-kai-501f","script":"kai","character":"借","reading":"jiè","description":"jiè：(1)暂时使用别人的财物等～用。～阅。～账。～据。～条。\n(2)暂时把财物等给别人使用～钱给人。\n(3)假托～口。～端。～故。～代。～景。～喻。～题发挥。\n(4)依靠凭～。～势。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-借"},{"id":"glyph-kai-5021","script":"kai","character":"倡","reading":"chàng；chāng","description":"chàng：(1)发动，首先提出～言，～始。～议。～导。提～。首～（首先提倡）。\n(2)古同唱”，唱和（hè）。\nchāng：(1)古代称唱戏的人～优。\n(2)古同娼”，妓女。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倡"},{"id":"glyph-kai-5026","script":"kai","character":"倦","reading":"juàn","description":"juàn：(1)疲乏疲～。～怠。～意。～容。～色。\n(2)对某种活动失去兴趣厌～。～飞（喻厌倦仕宦而归隐）。～游（厌倦游宦生涯）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倦"},{"id":"glyph-kai-503a","script":"kai","character":"债","reading":"zhai","description":"喻指应兑现的事情或所造成的损失\n借贷\n债zhài欠着的钱财～务。借～。公～。还～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-债"},{"id":"glyph-kai-503c","script":"kai","character":"值","reading":"zhí","description":"zhí：(1)价值，价钱币～。产～。贬～。升～。\n(2)物和价相当，引申有意义或有价值～百元。不～一文。～当。\n(3)数学上指演算所得结果数～。比～’数～。\n(4)遇到，逢着相～。～遇。正～。\n(5)当，轮到当～。～班。～勤。～更（gēng）。～星。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-值"},{"id":"glyph-kai-503e","script":"kai","character":"倾","reading":"qīng","description":"⒈侧，斜，歪～耳。～斜。前～。\n⒊倒塌～覆。～颓。\n⒋倒出，竭尽～诉。～箱倒箧。～其全力。\n⒍相互排挤～轧。以利相～。\n①斜倒墙壁～倒。\n②佩服，钦佩令人～倒。\n③倒出把这筐果皮、纸屑～倒在垃圾箱里。\n倾qǐng 1.顷，不久。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-倾"},{"id":"glyph-kai-5047","script":"kai","character":"假","reading":"jiǎ；jià","description":"jiǎ：(1)不真实的，不是本来的，与真”相对～山。～话。～冒。～释。～死。虚～。真～。弄虚作～。\n(2)借用，利用～借。～货。～道（借路）。～手（利用他人为自己办事）。～公济私。不～思索（用不着想）。\n(3)据理推断，有待验证的～设。～使。～令。～如。～若。\n〔～名〕日本文所用的字母，多借用汉字的偏旁。楷书称片～～”，草书称平～～”。\n真；\njià：照规定或经请求批准暂时离开工作或学习场所～日。～条。病～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-假"},{"id":"glyph-kai-504e","script":"kai","character":"偎","reading":"wēi","description":"wēi：紧挨着，亲密地靠着～傍。～倚。～依。依～。小孩儿～在母亲的怀里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偎"},{"id":"glyph-kai-504f","script":"kai","character":"偏","reading":"piān","description":"piān：(1)歪，不在中间～斜。～离。～旁。～僻。～远。～锋（a.书法上指用毛笔时笔锋斜出的笔势；b.泛指做文章从侧面着手的方法）。不～不倚。\n(2)不全面，不正确～爱。～见。～激。～狭。～执。～废。～颇。～听～信。\n(3)与愿望、预料或一般情况不相同～～。～巧。\n(4)谦辞，向人称自己已用过茶饭等我～过了，您请吃吧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偏"},{"id":"glyph-kai-505a","script":"kai","character":"做","reading":"zuò","description":"zuò：(1)进行工作或活动～活。～事。～工。～手脚（暗中进行安排）。\n(2)写文～诗。～文章。\n(3)制造～衣服。\n(4)当，为～人。～媒。～伴。～主。～客。看～。\n(5)装，扮～作。～功。～派。\n(6)举行，举办～寿。～礼拜。\n(7)用为芦苇可以～造纸原料。\n(8)结成（关系）～亲。～朋友。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-做"},{"id":"glyph-kai-505c","script":"kai","character":"停","reading":"tíng","description":"tíng：(1)止住，中止不动～止。～产。～学。～职。～顿。～刊。～战。～业。～滞。\n(2)总数分成几份，其中的一份十～儿有九～儿是好的。\n(3)暂时不继续前进～留。～泊。\n(4)妥当～妥。～当。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-停"},{"id":"glyph-kai-5065","script":"kai","character":"健","reading":"jiàn","description":"jiàn：(1)强壮，身体好～康。～全。康～。稳～。～美。～身。～旺。～在。～壮。～朗。保～。\n(2)善于，精力旺盛～步如飞。～谈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-健"},{"id":"glyph-kai-5076","script":"kai","character":"偶","reading":"ǒu","description":"ǒu：(1)用木头或泥土等制成的人形～像。木～戏。\n(2)双，对，成双成对，与奇（jī）”相对～数。～语（相对私语）。对～。无独有～。\n(3)事理上不一定要发生而发生的～或。～然。～合。～尔。～感。～发事件。\n(4)指丈夫或妻子佳～。配～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偶"},{"id":"glyph-kai-5077","script":"kai","character":"偷","reading":"tōu","description":"tōu：(1)窃取，趁人不知时拿人东西～窃。～吃。小～儿（tōur）。\n(2)行动瞒着人～～。～看。～听。～渡。～袭。～税。～天换日（喻暗中改变重大事物的真相以欺骗别人）。\n(3)抽出时间～空儿。～暇。～闲。\n(4)苟且～安。～生。～幸。～合苟容（苟且迎合别人的意思以求容身。亦称偷合取容”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偷"},{"id":"glyph-kai-507f","script":"kai","character":"偿","reading":"cháng","description":"报答;酬报\n补偿,抵偿\n满足,实现\n酬报\n①归还；低偿血债要用血来～。\n②满足如愿以～。\n【偿命】用生命偿还杀人～。\n⒈归还，赔给～还。～债。赔～。\n⒉抵当，抵补抵～。补～。得不～失。\n⒊回报，回答不可～也。\n⒋满足，实现如愿以～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-偿"},{"id":"glyph-kai-5085","script":"kai","character":"傅","reading":"fù","description":"fù：(1)辅相太～。少～。\n(2)教导～立德义”。\n(3)教导人的人师～。\n(4)附着，使附着～粉。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傅"},{"id":"glyph-kai-508d","script":"kai","character":"傍","reading":"bàng","description":"bàng：(1)靠依山～水。\n(2)临近～晚。～黑。～亮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傍"},{"id":"glyph-kai-50a8","script":"kai","character":"储","reading":"chǔ","description":"夸大,欺诳\n①存放；储藏～存、～蓄。\n②姓。\n【储君】帝王亲属中确定为继承皇位等最高统治权的人。\n【储蓄】\n①指积存的钱或物家家有～。\n②居民把暂时不用的现金存入银行或其他信用机构，以备需要时取用。\n储chǔ存，积蓄，藏着～存。～积。～蓄。～藏。～备。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-储"},{"id":"glyph-kai-50ac","script":"kai","character":"催","reading":"cuī","description":"cuī：(1)使赶快行动～促。～办。～讨。\n(2)使事物的产生、发展变化加快～化。～生。～眠。～奶。～肥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-催"},{"id":"glyph-kai-50b2","script":"kai","character":"傲","reading":"ào","description":"ào：(1)自高自大骄～。～岸（形容性格高傲）。～骨。～慢（轻视别人，对人没有礼貌）。～视。高～。孤～。\n(2)藐视，不屈～然。～霜斗雪。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傲"},{"id":"glyph-kai-50bb","script":"kai","character":"傻","reading":"shǎ","description":"shǎ：(1)愚蠢～子。～瓜。\n(2)老实，死心眼而不知变通～气。～干。犯～。～劲儿。～乐。～笑。\n(3)呆，愣吓～了。～眼了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-傻"},{"id":"glyph-kai-50cf","script":"kai","character":"像","reading":"xiàng","description":"xiàng：(1)相似好～。相（xiāng）～。～生（ａ．仿天然产物制成的工艺品；ｂ．中国宋、元两代以说唱为业的女艺人）。\n(2)比照人物做成的图形画～。塑～。雕～。绣～。肖～。\n(3)比如，比方～这样的事是值得注意的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-像"},{"id":"glyph-kai-50da","script":"kai","character":"僚","reading":"liáo","description":"liáo：(1)官官～。\n(2)旧指同在一起做官的～属（下属的官吏）。～友。～佐。幕～。\n(3)古代对一种奴隶或差役的称谓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僚"},{"id":"glyph-kai-50e7","script":"kai","character":"僧","reading":"sēng","description":"sēng：佛教指出家修行的人，梵语僧伽”的简称～侣。～尼。～人。～众。～俗。高～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僧"},{"id":"glyph-kai-50f5","script":"kai","character":"僵","reading":"jiāng","description":"jiāng：(1)仆倒～尸。\n(2)直挺挺，不灵活冻～。～硬。～直。～化。～卧。～死。～冷。～滞。\n(3)双方相持不下，两种意见不能调和弄～。～持。～局。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僵"},{"id":"glyph-kai-50fb","script":"kai","character":"僻","reading":"pì","description":"pì：(1)偏，距离中心地区远的偏～。～静。～陋。～野。～远。穷乡～壤。\n(2)不常见的冷～。生～。\n(3)性情古怪，不合群孤～。怪～。乖～。～戾。～性。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-僻"},{"id":"glyph-kai-5112","script":"kai","character":"儒","reading":"rú","description":"rú：(1)指读书人～生。腐～。通～（指博识多闻的大学者）。～林（儒者之林，旧指学术界）。～雅（读书人所具有的温文尔雅的风貌）。\n(2)中国春秋战国时代以孔子、孟子为代表的一个学派～家。～教（即孔教”）。～士。～术。～学。\n(3)古同懦”，懦弱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-儒"},{"id":"glyph-kai-513f","script":"kai","character":"儿","reading":"ér","description":"儿女,父母所生的子女,第一代后裔\n①小孩子婴～。\n③儿子～女。\n④词尾，同前一字连成一个卷舌音小孩～。\n【儿歌】儿童文学的一种。一般与童谣合称为儿童歌谣。儿歌是指反映儿童的生活和思想感情的诗歌。形式短小活泼，用辞简明，节奏明快，韵律响亮，适合儿童接受和传唱。\n童谣则指流传于儿童中间的歌谣。\n【儿化】〈语〉汉语普通话和某些方言中的一种语音现象，即后缀'儿'字不自成音节，而和前头的音节合在一起，使前一音节的韵母成为卷舌韵母。又叫儿化韵。\n【儿化韵】见【儿化】。\n【儿童节】见【六一儿童节】。\n【儿童文学】适合少年儿童阅读的各种体裁的文学作品。包括童话、诗歌、小说、故事、戏剧等形式，要求通俗易懂、生动活泼，适应不同年龄的少年儿童的智力和爱好。\n【儿童心理学】心理学分支之一。研究儿童心理发生、发展的一般规律及各年龄阶段的心理特征。\n【儿戏】像小孩子那么闹着玩。比喻对重要的工作或事情不负责、不认真视同～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-儿"},{"id":"glyph-kai-5141","script":"kai","character":"允","reading":"yǔn","description":"yǔn：(1)答应，认可～许。～诺。不～。\n(2)公平得当～当。公～。\n(3)信，实～恭克让（诚信，谦逊能够忍让）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-允"},{"id":"glyph-kai-5143","script":"kai","character":"元","reading":"yuán","description":"yuán：(1)头、首、始、大～凶。～首。～旦。～年。～勋。～帅。状～（科举考试第一名）。\n(2)基本单～。～件。～气（精气，根本）。～素。～音。\n(3)同圆”⑦。\n(4)未知数一～二次方程。\n(5)中国朝代名～代。～曲。\n(6)姓。\n(7)古同玄”，清代避康熙皇帝（玄烨）名讳，以元”代玄”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-元"},{"id":"glyph-kai-5144","script":"kai","character":"兄","reading":"xiōng","description":"xiōng：哥哥胞～。堂～。表～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兄"},{"id":"glyph-kai-5145","script":"kai","character":"充","reading":"chōng","description":"chōng：(1)满、足～足。～实。～分（fèn）（a.足够；b.尽量）。～沛。～裕。\n(2)填满，装满填～。～满（a.填满，布满；b.充分具有）。～耳不闻。～电」牛～栋。\n(3)当，担任～当。～军。\n(4)假装冒～。～数（shù）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-充"},{"id":"glyph-kai-5146","script":"kai","character":"兆","reading":"zhào","description":"zhào：(1)古代占验吉凶时灼龟甲所成的裂纹卜～。\n(2)事物发生前的征候或迹象，预示预～。佳～。瑞雪～丰年。\n(3)数名，等于百万（古代指万亿）～周（电磁波频率单位，每秒一百万周的频率为一兆周）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兆"},{"id":"glyph-kai-5148","script":"kai","character":"先","reading":"xiān","description":"xiān：(1)时间在前的，次序在前的，与后”相对～前。～期。原～。～驱。～河（中国古代帝王先祭黄河，后祭海，以河为海的本源，后称倡导在先的事物）。～觉（jué）。～见之明。～发制人。\n(2)家族或民族的较早的一代或几代～人。～世（祖先）。～民。\n(3)对死去的人的尊称～祖。～父。～哲（指已去世的有才德的思想家）。～烈。～贤。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-先"},{"id":"glyph-kai-5149","script":"kai","character":"光","reading":"guāng","description":"⒈光线，照亮物体因而可用眼睛看到物体的那种东西～亮。～芒。日～。电灯～。～的传播速度，每秒约30万公里。〈喻〉心怀坦白，公正无私～明磊落。正大～明。\n⒉荣耀，荣誉，耀眼的～彩。～荣。～辉灿烂。\n⒊敬词欢迎～临。谢谢～顾。\n⒋景物春～明媚。美好风～。\n①境况，情景我们的～景一年更比一年强。\n②〈表〉估计看～景怕是要下雨。\n⒌表面平滑，使平滑～滑。～溜溜。打～。刨～。\n⒍完，一点儿不剩吃～。消灭～。\n⒎裸露～脚行走。～着上身。\n⒏只，单～剩这一间屋了。～靠少数人是做不好这件事的。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-光"},{"id":"glyph-kai-514b","script":"kai","character":"克","reading":"kè","description":"⒈至\n⒋剋、\n⒈至\n⒈攻破，战胜连～数城。～敌制胜。\n⒉制伏，抑制～服。～制。奉公～己。\n⒋通\"刻\"。雕刻，苛刻～画。性俭～。\n⒌能够～勤～俭。～尽职责。\n⒍消化～食。\n⒎公制重量单位，旧称\"公分\"。一千克为一公斤。\n⒏藏族地区的容量单位，一克青稞约为二十五市斤。也是土地的面积单位，一克约为一市亩。\n克kēi 1.训斥;狠狠批评。 2.方言。抠取。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-克"},{"id":"glyph-kai-514d","script":"kai","character":"免","reading":"miǎn","description":"miǎn：(1)去掉，除掉～除。～税。～费。～官。～检。罢～。豁～。\n(2)不被某种事物所涉及避～。～疫。～不了。在所难～。\n(3)不可，不要闲人～进。\n(4)古同勉”，勉励。\n(5)古同娩”，分娩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-免"},{"id":"glyph-kai-5151","script":"kai","character":"兑","reading":"duì；ruì；yuè","description":"duì：(1)交换～换（用一种货币换另一种货币）。～现。汇～（两地通过信件或电报交换款项）。\n(2)液体从一个容器注入另一个容器，一种东西搀到另一种东西里去～点热水。\n(3)八卦之一，代表沼泽。\n(4)直松柏斯～”。\nruì：古同锐”，尖锐。\nyuè：古同悦”，喜悦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兑"},{"id":"glyph-kai-5154","script":"kai","character":"兔","reading":"tù","description":"tù：(1)哺乳动物，耳长，尾短，上唇中间裂开，后肢较长，跑得快～子。～脱（迅速地逃走）。～毫笔。～起鹘落（鹘”，打猎用的猛禽。兔子才起来而鹘已经扑下去，喻动作敏捷。亦喻作书画或写文章下笔迅捷）。\n(2)古称娈童（指被当作女性玩弄的美貌男子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兔"},{"id":"glyph-kai-515a","script":"kai","character":"党","reading":"dǎng","description":"不鲜明\n美,善,正直◇作谠”\n知晓,解悟\n偏私,偏袒\n①政党，代表某一阶级、阶层利益的政治组织。在我国特指中国共产党。\n②为私利而结成的集团结～营私。\n③偏袒～同伐异。\n④旧时指亲族父～、母～。\n⑤姓。\n【党阀】政党内把持大权、专横跋扈、拉山头、搞宗派的头目。\n【党锢之祸】东汉末因宦官专权而对世家大族进行的打击。第一次党锢之祸发生在恒帝时，李膺等抨击宦官集团，被诬为诽讪朝廷，200多名'党人'被捕，释放后终身不许做官\n。第二次党锢之祸发生在灵帝时，窦武起用'党人'谋诛宦官，事泄被杀。李膺等百余人亦被处死，流徙囚禁六七百人。被禁锢罢官者，祸及'党人'五族。\n【党同伐异】偏袒同党，攻击异己。\n【党卫军】第二次世界大战期间法西斯德国纳粹党的特务和军事组织。成立于1925年。最初为希特勒的私人卫队。希特勒执政后成为特务机构。曾以血腥手段迫害和屠杀德国国\n内进步势力、占领区居民和犹太人，并直接参加法西斯侵略战争。1946年在纽伦堡审判中被定为犯罪组织。\n【党项人】古族名。羌人的一支。原分布于青海、四川一带，主要从事畜牧业。唐时受吐蕃压迫，迁至甘肃、宁夏、陕北一带。北宋时曾建立西夏政权。\n【党羽】反动集团中与头领一起为非作歹的帮凶。\n【党政分工】指党组织和行政部门的领导分工负责。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-党"},{"id":"glyph-kai-515c","script":"kai","character":"兜","reading":"dōu","description":"dōu：(1)古代作战时戴的盔～鍪。\n(2)口袋网～。\n(3)做成兜形把东西拢住～风。用手巾～着。\n(4)环绕，围绕～抄。～剿。～圈子。\n(5)招揽～售。～销。～揽。\n(6)承担，包下来出事我～着。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兜"},{"id":"glyph-kai-5162","script":"kai","character":"兢","reading":"jīng","description":"jīng：〔～～〕小心，谨慎，如～～业业”、战战～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兢"},{"id":"glyph-kai-5165","script":"kai","character":"入","reading":"rù","description":"rù：(1)进，由外到内进～。～梦。\n(2)适合，恰好合适～选。～耳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-入"},{"id":"glyph-kai-5168","script":"kai","character":"全","reading":"quán","description":"quán：(1)完备，齐备，完整，不缺少齐～。完～。智勇双～。求～责备。\n(2)整个，遍～部。～国。～民。～神贯注。～心～意。\n(3)都代表～来了。\n(4)使不受损伤保～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-全"},{"id":"glyph-kai-516b","script":"kai","character":"八","reading":"bā","description":"bā：数名，七加一（在钞票和单据上常用大写捌”代）～面玲珑。～卦（《周易》中的八种基本图形）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-八"},{"id":"glyph-kai-516c","script":"kai","character":"公","reading":"gōng","description":"gōng：(1)正直无私，为大家利益～正。～心。大～无私。\n(2)共同的，大家承认的～理。～式。～海。～制。\n(3)国家，社会，大众～共。～安（社会整体的治安）。～众。～民。～论（公众的评论）。\n(4)让大家知道～开。～报。～然。\n(5)封建制度最高爵位三～（中国周代指太师”、太傅”、太保”；西汉指大司徒”、大司马”、大司空”）。～子。～主。\n(6)敬辞，尊称男子海～。包～。诸～（各位）。\n(7)雄性的～母。～畜。\n(8)对长辈和年老人的称呼～～。外～（外祖父）。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-公"},{"id":"glyph-kai-516d","script":"kai","character":"六","reading":"liù；lù","description":"(2)中国古代乐谱的记音符号，相当于简谱5”。\nlù：〔～安〕地名，在中国安徽省。\n〔～合〕地名，在中国江苏省。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-六"},{"id":"glyph-kai-5170","script":"kai","character":"兰","reading":"lán","description":"兰花\n兰属\n⒈兰花，多年生常绿草本，丛生，叶细长，花清香。种类很多，常见的有草～、建～、墨～、蕙～等。供观赏。\n⒉兰草，多年生草本。叶子卵圆形，边缘呈锯齿状，有香味，秋末开花，供观赏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兰"},{"id":"glyph-kai-5171","script":"kai","character":"共","reading":"gòng；gōng","description":"gòng：(1)相同，一样～性。～同。同甘～苦。\n(2)彼此都具有、使用或承受患难与～。休戚与～。\n(3)一起，一齐～鸣。～勉。～议。～处（chǔ）。\n(4)总计，合计～计。总～。\n(5)与，和落霞与孤鹜齐飞，秋水～长天一色。”\n(6)共产党”的简称。\n同；\ngōng：(1)古同恭”，恭敬。\n(2)古同供”，供奉，供给。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-共"},{"id":"glyph-kai-5173","script":"kai","character":"关","reading":"guān","description":"门闩。闩门的横木\n关口,隘门\n⒈闭，合把门～上。～好窗子。〈引〉拘禁～押。\n⒉门闩拔～而出。\n⒊〈古〉要塞或设立守卫的处所～口。剑门～。〈引〉征收出口、进口货物税的机构海～。\n⒋重要的转折点或不易度过的时机紧要～头。共度难～。\n⒌起转折和联结作用的部分腕～节。\n⒍牵连，涉及～连。～联。息息相～。与他无～。\n⒎重视，爱护，照顾～注。～切。～心。～怀。请多～照。\n①事物间的联系学习与工作的～系。\n②人与人或人与事物的联系朋友～系。人与环境的～系。\n③牵涉，影响这项事～系重大。\n④〈表〉某种证件党的组织～系。\n⑤泛指原因、条件等由于时间～系，不再讲了。\n关wān 1.引满弓。\n关wǎn 1.绾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-关"},{"id":"glyph-kai-5174","script":"kai","character":"兴","reading":"xīng","description":"⒉发动，举办，提倡～修水利。～办工厂。大～勤俭节约之风。\n⒊旺盛～旺。～盛。\n⒋流行，盛行～起。时～。\n⒌允许不～乱吵。\n⒍〈方〉或许你～买，～不买。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兴"},{"id":"glyph-kai-5175","script":"kai","character":"兵","reading":"bīng","description":"bīng：(1)武器～器。～刃。～不血刃（兵器上面没有沾血，指不经过战斗而取得胜利）。\n(2)战士，军队～士。～卒。～丁。～戎相见（指武装冲突）。\n(3)与军事或战争有关事物的统称～法。～家。～机。～衅（战争的争端）。～书。～谏（进谏时以武力要挟，迫使必从）。～荒马乱。～贵神速。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兵"},{"id":"glyph-kai-5176","script":"kai","character":"其","reading":"qí；jī","description":"qí：(1)第三人物代词，相当于他（她）”、他们（她们）”、它（它们）”；他（她）的”、他们（她们）的”、它（们）的”各得～所。莫名～妙。三缄～口。独行～是。自食～果。\n(2)指示代词，相当于那”、那个”、那些”～他。～余。～次。文如～人。名副～实。言过～实。\n(3)那里面的～中。只知～一，不知～二。\n(4)连词，相当于如果”、假使”～如是，熟能御之？”\n(5)助词，表示揣测、反诘、命令、劝勉～如土石何？”\n(6)词尾，在副词后极～快乐。大概～。\njī：〔郦食（yì）～〕中国汉代人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-其"},{"id":"glyph-kai-5177","script":"kai","character":"具","reading":"jù；jv","description":"jù：(1)器物器～。\n(2)备有～备。～有。别～只眼（形容具有独到的眼光和见解）。\n(3)备，办～呈。～结。～名。～领。敬～菲酌。\n(4)古同俱”，都，完全。\n(5)量词，用于某些器物和棺材、尸体座钟一～。一～男尸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-具"},{"id":"glyph-kai-5178","script":"kai","character":"典","reading":"diǎn","description":"diǎn：(1)可以作为标准的书籍～籍。字～。词～。经～。引经据～。\n(2)标准，法则～章。～制。～故（a.典制和掌故；b.诗文里引用的古书中的故事或词句）。～范。～雅。～礼。～型。\n(3)指典礼盛～。大～。\n(4)主持，主管～试（主持科举考试之事）。～狱。\n(5)活买活卖，到期可以赎～卖。～押。～契。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-典"},{"id":"glyph-kai-5179","script":"kai","character":"兹","reading":"zī；cí","description":"zī：(1)这，这个，此～日。～行（xíng）。\n(2)现在～聘请某先生为本校教员。\n(3)年今～。来～。\n(4)古同滋”，增益；多。\n(5)古代称草席。\ncí：〔龟（qiū）～〕见龟3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兹"},{"id":"glyph-kai-517b","script":"kai","character":"养","reading":"yǎng","description":"供养,奉养;抚育\n监门之养。\n供养卒大恩。\n⒈抚育，供给～育。供～。\n⒉生育，生小孩生～。\n⒊教育，培育教～。培～。从小～成劳动习惯。\n⒋喂动物，培植花草饲～。～鸭。～猪。～殖。～鸟。～花。～草。\n⒌休息，调理，滋补。休～。保～。滋～。〈引〉保护修理 修～。～路。\n⒍扶助，帮助以工～农。\n⒎非亲生的但有抚育关系的～母。～女。\n久长。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-养"},{"id":"glyph-kai-517c","script":"kai","character":"兼","reading":"jiān","description":"jiān：(1)加倍，把两份并在一起～旬（两个十天）。～程。～并。\n(2)同时涉及或所具有的不只一方面～而有之。～收并蓄。～顾。～职。～任。～课。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兼"},{"id":"glyph-kai-517d","script":"kai","character":"兽","reading":"shòu","description":"四足的哺乳动物,多指野兽\n山深而兽往之","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-兽"},{"id":"glyph-kai-5180","script":"kai","character":"冀","reading":"jì","description":"jì：(1)希望～求（希望得到）。～幸。～望。～希。\n(2)中国河北省的别称。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-冀"},{"id":"glyph-kai-5185","script":"kai","character":"内","reading":"nèi；nà","description":"nèi：(1)里面，与外”相对～部。～外。～定。～地。～阁。～行（háng）。～涵。\n(2)称妻子或妻子家的亲戚～人。～亲。～弟。\n(3)亲近～君子而外小人。\n外；\nnà：古同纳”，收入；接受。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-内"}];
